INSERT INTO _n1_b1_guard_0099(ok) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM japanese_jlpt_daily_sessions s JOIN japanese_jlpt_study_plans p ON p.id=s.plan_id WHERE p.plan_code='N1_2027_JUL' AND s.study_date BETWEEN '2026-10-01' AND '2026-10-14' AND (s.status <> 'not_started' OR s.started_at IS NOT NULL OR s.completed_at IS NOT NULL)) THEN 1 ELSE 0 END;
INSERT INTO _n1_b1_words_0099(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0083','2026-10-01','設立','せつりつ','설립','会社・団体・機関などを新しく組織して作ること。','地域の文化を守ることを目的に、新しい財団が設立された。','지역 문화를 지키는 것을 목적으로 새로운 재단이 설립되었다.'),
('n1-0984','2026-10-01','及ぶ','およぶ','미치다; 이르다; 필적하다','影響・範囲・数量などがある地点・程度に達する。また、能力が相手に匹敵する。','今回のシステム障害の影響は国内の複数拠点に及んだ。','이번 시스템 장애의 영향은 국내 여러 거점에 미쳤다.'),
('n1-0081','2026-10-01','名誉','めいよ','명예; 영예','社会から高く評価され、尊敬や信用を受けること。また、その評価や栄誉。','長年の研究成果が認められ、名誉ある賞を受けることになった。','오랜 연구 성과를 인정받아 영예로운 상을 받게 되었다.'),
('n1-0084','2026-10-01','非難','ひなん','비난','人の行為や欠点などを取り上げ、悪いとして責めること。','十分な説明をしないまま計画を変更したとして、会社は利用者から非難を受けた。','충분한 설명 없이 계획을 변경했다는 이유로 회사는 이용자들의 비난을 받았다.'),
('n1-0086','2026-10-01','記述','きじゅつ','기술; 서술','事実や内容を文章として書き表すこと。また、その文章。','報告書には、実験の手順と結果を客観的に記述する必要がある。','보고서에는 실험 절차와 결과를 객관적으로 서술할 필요가 있다.'),
('n1-1037','2026-10-01','取り組む','とりくむ','몰두하다; 적극적으로 임하다','課題・仕事などに正面から向き合い、努力して進める。','会社全体で業務のデジタル化に取り組んでいる。','회사 전체가 업무 디지털화에 적극적으로 임하고 있다.'),
('n1-0089','2026-10-01','要請','ようせい','요청; 요구','必要なこととして、相手に実現や対応を強く求めること。','自治体は大雪に備え、不要不急の外出を控えるよう住民に要請した。','지자체는 폭설에 대비해 불필요한 외출을 자제해 달라고 주민들에게 요청했다.'),
('n1-0108','2026-10-01','独自','どくじ','독자적; 고유함','他とは異なり、そのものだけに特有の方法・性質・立場を持つこと。','この会社は独自の技術を生かし、海外市場でも高い評価を得ている。','이 회사는 독자적인 기술을 살려 해외 시장에서도 높은 평가를 받고 있다.'),
('n1-0091','2026-10-01','進行','しんこう','진행; 진척','物事が前へ進むこと。また、予定や手順に沿って物事を進めること。','工事の進行が予定より遅れているため、工程を見直すことになった。','공사 진행이 예정보다 늦어져 공정을 재검토하게 되었다.'),
('n1-0095','2026-10-01','処分','しょぶん','처분; 처리; 징계 처분','不要な物を捨てたり売ったりして片付けること。また、規則違反などに対して罰や措置を決定すること。','保存期限を過ぎた書類は、規定に従って適切に処分しなければならない。','보존 기한이 지난 서류는 규정에 따라 적절히 처분해야 한다.'),
('n1-1071','2026-10-01','築く','きずく','쌓다; 구축하다','建物・土台などを作る。また比喩的に、信頼・地位・関係などを長い時間をかけて作り上げる。','顧客との信頼関係を築くには、約束を地道に守り続けることが重要だ。','고객과 신뢰 관계를 구축하려면 약속을 꾸준히 지키는 것이 중요하다.'),
('n1-0111','2026-10-01','一切','いっさい','일절; 일체; 전부','すべてのこと。多く否定表現とともに用いて、『まったく何も』の意を表す。','試験中は、携帯電話などの電子機器を一切使用してはいけない。','시험 중에는 휴대전화 등의 전자기기를 일절 사용해서는 안 된다.'),
('n1-0100','2026-10-01','形成','けいせい','형성; 만들어짐','ある形・状態・関係などを作り上げること。また、次第に作られること。','信頼関係の形成には、日々の小さな約束を守ることが重要だ。','신뢰 관계 형성에는 매일 작은 약속을 지키는 것이 중요하다.'),
('n1-0103','2026-10-01','条約','じょうやく','조약','国家間などで、権利や義務について正式に取り決めた国際的な合意。','両国は長期にわたる交渉の末、新たな環境保護条約に署名した。','양국은 오랜 협상 끝에 새로운 환경보호 조약에 서명했다.'),
('n1-1074','2026-10-01','負う','おう','지다; 책임지다; 입다','責任・義務・負傷・損害などを引き受ける。また、背中に物を載せる。','管理者は最終的な判断について責任を負う。','관리자는 최종 판단에 대해 책임을 진다.'),
('n1-0105','2026-10-01','民主','みんしゅ','민주; 민주주의적 원리','政治において国民を主権者とし、その意思に基づいて社会を運営しようとする考え方や原理。','民主的な手続きを守るには、少数意見にも耳を傾ける必要がある。','민주적인 절차를 지키려면 소수 의견에도 귀를 기울일 필요가 있다.'),
('n1-0163','2026-10-01','従来','じゅうらい','종래; 이전부터 지금까지; 기존의','以前からこれまで。従来の方法・制度など、これまで一般に用いられてきたものを指す場合にも使う。','新方式では、従来より少ない手順で申請を完了できるようになった。','새 방식에서는 기존보다 적은 절차로 신청을 완료할 수 있게 되었다.'),
('n1-0110','2026-10-01','規定','きてい','규정; 규정하다','規則として内容や条件を定めること。また、その定められた内容。','個人情報は社内規定に従って管理し、目的外には利用してはならない。','개인정보는 사내 규정에 따라 관리하고 목적 외에는 이용해서는 안 된다.'),
('n1-0114','2026-10-01','民族','みんぞく','민족','言語・文化・歴史・生活習慣などを共有し、集団としての意識を持つ人々。','この地域には異なる民族が暮らし、それぞれ独自の文化を受け継いでいる。','이 지역에는 서로 다른 민족이 살며 각자의 고유한 문화를 이어가고 있다.'),
('n1-0115','2026-10-01','獲得','かくとく','획득','努力や競争などを通じて、求めていたものを手に入れること。','新規顧客を獲得するため、サービス内容を全面的に見直した。','신규 고객을 확보하기 위해 서비스 내용을 전면적으로 재검토했다.'),
('n1-0121','2026-10-02','対処','たいしょ','대처; 대응','問題や困難な状況に対して、状況に合った方法で処理すること。','障害が発生した際に迅速に対処できるよう、手順書を事前に整備しておく。','장애가 발생했을 때 신속히 대처할 수 있도록 절차서를 미리 정비해 둔다.'),
('n1-1079','2026-10-02','仕える','つかえる','섬기다; 모시다; 상관 아래에서 일하다','目上の人・君主などのそばで働き、その人のために務める。','彼は若い頃からその師に仕え、多くの技術を学んだ。','그는 젊을 때부터 그 스승을 모시며 많은 기술을 배웠다.'),
('n1-0167','2026-10-02','有力','ゆうりょく','유력; 영향력이 큼; 가능성이 높음','勢力や影響力が強いこと。また、実現・当選・成立などの可能性が高いこと。','複数の案を比較した結果、この方式が最も有力な候補として残った。','여러 안을 비교한 결과 이 방식이 가장 유력한 후보로 남았다.'),
('n1-0126','2026-10-02','事項','じこう','사항; 항목','ある物事を構成する個々の項目や内容。','申請前に注意事項をよく読み、必要な書類がそろっているか確認してください。','신청 전에 주의 사항을 잘 읽고 필요한 서류가 모두 갖춰졌는지 확인해 주세요.'),
('n1-0130','2026-10-02','概念','がいねん','개념','物事の共通する性質をまとめて捉えた、一般的な意味や考え。','専門用語を理解するには、まずその背景にある基本概念を押さえる必要がある。','전문용어를 이해하려면 먼저 그 배경에 있는 기본 개념을 파악할 필요가 있다.'),
('n1-1081','2026-10-02','欠く','かく','결여하다; 빠뜨리다; 부족하다','必要なものを持っていない。また、必要な要素を抜く・失う。','客観的な根拠を欠く主張は、説得力を持ちにくい。','객관적인 근거가 결여된 주장은 설득력을 갖기 어렵다.'),
('n1-0133','2026-10-02','暗殺','あんさつ','암살','政治家など重要な人物を、ひそかに計画して殺害すること。','その事件をきっかけに、要人暗殺を防ぐための警備体制が強化された。','그 사건을 계기로 요인 암살을 막기 위한 경비 체계가 강화되었다.'),
('n1-0170','2026-10-02','正当','せいとう','정당함; 타당함','道理・法律・社会的な基準などに照らして、理由や扱いが適切であること。','契約を解除するには、相手が納得できる正当な理由を示す必要がある。','계약을 해지하려면 상대가 납득할 수 있는 정당한 이유를 제시할 필요가 있다.'),
('n1-0134','2026-10-02','世代','せだい','세대','ほぼ同じ時期に生まれ、似た社会的経験を共有する人々の層。親子の年代差を表す単位としても用いる。','世代によって情報の集め方が異なるため、広報手段も一つに絞れない。','세대에 따라 정보를 모으는 방식이 달라 홍보 수단도 하나로 한정할 수 없다.'),
('n1-0136','2026-10-02','分離','ぶんり','분리','一つになっているものを分けて離すこと。また、分かれて離れること。','個人情報を一般の業務データから分離して管理する仕組みに変更した。','개인정보를 일반 업무 데이터와 분리해 관리하는 구조로 변경했다.'),
('n1-1086','2026-10-02','唱える','となえる','주장하다; 외치다; 읊다','意見・主義などを強く主張する。また、決まった文句・祈りなどを声に出して言う。','研究者は従来の説に疑問を唱え、新しい解釈を提示した。','연구자는 기존 학설에 의문을 제기하고 새로운 해석을 제시했다.'),
('n1-0244','2026-10-02','知的','ちてき','지적; 지성적인','知識・知性・思考に関係するさま。また、知性を感じさせるさま。','知的好奇心を持ち続けることは、新しい分野を学ぶ大きな原動力になる。','지적 호기심을 계속 유지하는 것은 새로운 분야를 배우는 큰 원동력이 된다.'),
('n1-0137','2026-10-02','定義','ていぎ','정의; 정의하다','言葉や概念が何を意味するか、その範囲や内容を明確に定めること。また、その内容。','議論を始める前に、ここでいう『成功』の定義を共有しておく必要がある。','논의를 시작하기 전에 여기서 말하는 ''성공''의 정의를 공유해 둘 필요가 있다.'),
('n1-0138','2026-10-02','確立','かくりつ','확립; 정립','制度・方法・理論・立場などを、確かなものとしてしっかり成立させること。','再発を防ぐには、個人の注意だけでなく組織的な確認手順を確立する必要がある。','재발을 막으려면 개인의 주의뿐 아니라 조직적인 확인 절차를 확립할 필요가 있다.'),
('n1-1099','2026-10-02','耐える','たえる','견디다; 버티다','苦痛・圧力・厳しい条件などに負けず、持ちこたえる。','この建物は強い地震にも耐えられるよう設計されている。','이 건물은 강한 지진에도 견딜 수 있도록 설계돼 있다.'),
('n1-0139','2026-10-02','合併','がっぺい','합병','二つ以上の会社・団体・組織などが一つにまとまること。また、一つにまとめること。','両社は競争力を高めるため、来年四月に合併することで合意した。','두 회사는 경쟁력을 높이기 위해 내년 4월에 합병하기로 합의했다.'),
('n1-0250','2026-10-02','忠実','ちゅうじつ','충실; 충실함; 정확히 따름','人や約束などに誠実に従うこと。また、原文・事実・指示などを正確に再現したり守ったりすること。','翻訳では単語を置き換えるだけでなく、原文の意図を忠実に伝える必要がある。','번역에서는 단어를 바꾸는 것뿐 아니라 원문의 의도를 충실히 전달할 필요가 있다.'),
('n1-0141','2026-10-02','導入','どうにゅう','도입','制度・技術・設備などを新たに取り入れて用いること。','業務効率を高めるため、来月から新しい管理システムを導入する。','업무 효율을 높이기 위해 다음 달부터 새로운 관리 시스템을 도입한다.'),
('n1-0142','2026-10-02','象徴','しょうちょう','상징','抽象的な概念や特徴を、具体的な物や人物などによって代表して表すこと。また、そのもの。','この建物は、戦後の復興を象徴する存在として長く保存されてきた。','이 건물은 전후 부흥을 상징하는 존재로 오랫동안 보존되어 왔다.'),
('n1-0143','2026-10-02','連邦','れんぽう','연방','複数の州や国などが一定の自治権を保ちながら、一つの中央政府の下で結び付いた国家形態。','その国では、連邦政府と各州政府がそれぞれ異なる権限を持っている。','그 나라에서는 연방 정부와 각 주 정부가 각각 다른 권한을 가지고 있다.');
INSERT INTO _n1_b1_words_0099(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0144','2026-10-03','受け入れ','うけいれ','수용; 받아들임','人・物・考え・要求などを受け取り、認めたり取り込んだりすること。','外国人材の受け入れを進めるには、生活面の支援体制も整える必要がある。','외국인 인재 수용을 추진하려면 생활 측면의 지원 체계도 정비할 필요가 있다.'),
('n1-1115','2026-10-03','滅ぼす','ほろぼす','멸망시키다; 파멸시키다','国・組織・生物の集団などを完全に滅亡させる。また、将来や生活を台無しにする。','長期的な環境破壊は多くの生物種を滅ぼすおそれがある。','장기적인 환경 파괴는 많은 생물종을 멸종시킬 우려가 있다.'),
('n1-0265','2026-10-03','単独','たんどく','단독; 혼자서','他と一緒ではなく、一人または一つだけで行うこと。','この作業を新人が単独で担当するのは危険なので、当面は二人一組で行う。','이 작업을 신입이 단독으로 담당하는 것은 위험하므로 당분간 두 명이 한 조로 진행한다.'),
('n1-0146','2026-10-03','任命','にんめい','임명','ある人を特定の役職や任務に就かせること。','新しい責任者には、現場経験の豊富な社員が任命された。','새 책임자로는 현장 경험이 풍부한 사원이 임명되었다.'),
('n1-0148','2026-10-03','争い','あらそい','다툼; 분쟁; 경쟁','互いに対立して争うこと。また、勝敗や利益などをめぐって競い合うこと。','資源をめぐる争いが長期化し、地域の経済にも深刻な影響が出ている。','자원을 둘러싼 분쟁이 장기화되어 지역 경제에도 심각한 영향이 나타나고 있다.'),
('n1-1116','2026-10-03','犯す','おかす','범하다; 저지르다; 위반하다','罪・過ち・規則違反など、してはならない行為をする。','同じ過ちを犯さないため、原因を記録して共有した。','같은 잘못을 저지르지 않기 위해 원인을 기록해 공유했다.'),
('n1-0150','2026-10-03','所属','しょぞく','소속','組織や団体などの一員として、その中に属していること。','申請書には氏名だけでなく、所属する部署名も記入してください。','신청서에는 이름뿐 아니라 소속 부서명도 기입해 주세요.'),
('n1-0346','2026-10-03','活発','かっぱつ','활발; 활기참','活動・動き・議論などが盛んで、勢いがあること。','会議では立場の違う参加者からも活発に意見が出され、予定時間を大きく超えた。','회의에서는 입장이 다른 참가자들에게서도 활발하게 의견이 나와 예정 시간을 크게 넘겼다.'),
('n1-0152','2026-10-03','規制','きせい','규제','法律や規則によって、行為・活動・数量などに一定の制限を設けること。','環境への負荷を減らすため、工場の排出物に対する規制が強化された。','환경 부담을 줄이기 위해 공장 배출물에 대한 규제가 강화되었다.'),
('n1-0153','2026-10-03','司法','しほう','사법','法律に基づいて争いを裁き、法を具体的な事件に適用する国家作用。','民主主義を維持するには、行政や立法から独立した司法の役割が重要である。','민주주의를 유지하려면 행정이나 입법으로부터 독립된 사법의 역할이 중요하다.'),
('n1-1122','2026-10-03','施す','ほどこす','베풀다; 실시하다; 가하다','人に恩恵を与える。また、処置・加工・装飾・肥料などを加える。','建物には耐震補強が施され、安全性が高められた。','건물에는 내진 보강이 실시되어 안전성이 높아졌다.'),
('n1-0350','2026-10-03','著名','ちょめい','저명; 유명','名前や実績が世間に広く知られていること。','講演会には、この分野で著名な研究者が国内外から招かれた。','강연회에는 이 분야에서 저명한 연구자들이 국내외에서 초청되었다.'),
('n1-0154','2026-10-03','強制','きょうせい','강제','本人の意思にかかわらず、権力や力によって無理に行わせること。','会社が私物の端末利用を強制することには、情報管理上の問題もある。','회사가 개인 단말 사용을 강제하는 데에는 정보 관리상의 문제도 있다.'),
('n1-0155','2026-10-03','階級','かいきゅう','계급; 계층','地位・身分・職務などによって区分された等級。また、社会的・経済的条件の共通する人々の層。','当時の社会では、出身階級によって受けられる教育にも大きな差があった。','당시 사회에서는 출신 계급에 따라 받을 수 있는 교육에도 큰 차이가 있었다.'),
('n1-1125','2026-10-03','遂げる','とげる','이루다; 완수하다','目標・任務・発展などを最後まで成し遂げ、結果を得る。','長年の研究が実を結び、ついに大きな成果を遂げた。','오랜 연구가 결실을 맺어 마침내 큰 성과를 이루었다.'),
('n1-0157','2026-10-03','関与','かんよ','관여; 관련하여 참여함','ある事柄に関係し、その進行・判断・結果などにかかわること。','第三者が意思決定にどこまで関与したのか、詳しい調査が行われている。','제3자가 의사 결정에 어디까지 관여했는지 상세한 조사가 이루어지고 있다.'),
('n1-0366','2026-10-03','不可欠','ふかけつ','불가결; 필수적','目的を達成したり物事を成り立たせたりする上で、なくてはならないこと。','安全なシステム運用には、定期的なバックアップが不可欠だ。','안전한 시스템 운영에는 정기적인 백업이 필수적이다.'),
('n1-0158','2026-10-03','原則','げんそく','원칙; 원칙적으로','物事を行う上で基本として守るべき規則や考え方。また、『原則として』の形で基本的な扱いを示す。','社外へのデータ持ち出しは原則として禁止されている。','사외로 데이터를 반출하는 것은 원칙적으로 금지되어 있다.'),
('n1-0160','2026-10-03','達成','たっせい','달성; 성취','目標や目的としていたことを成し遂げること。','年度目標を達成するには、残り三か月で優先順位を見直す必要がある。','연간 목표를 달성하려면 남은 3개월 동안 우선순위를 재검토할 필요가 있다.'),
('n1-0162','2026-10-03','限定','げんてい','한정; 제한','範囲・数量・期間・対象などを一定のものに限って定めること。','この機能は現在、一部の利用者に限定して試験的に提供されている。','이 기능은 현재 일부 이용자에 한정하여 시험적으로 제공되고 있다.'),
('n1-0165','2026-10-04','統合','とうごう','통합','複数の組織・制度・機能・情報などを一つにまとめること。','重複していた顧客データを統合し、一つのシステムで管理することになった。','중복되어 있던 고객 데이터를 통합해 하나의 시스템에서 관리하게 되었다.'),
('n1-1137','2026-10-04','掲げる','かかげる','내걸다; 내세우다; 제시하다','旗・看板などを高く上げる。また、目標・理念・方針などを公に示す。','会社は『安全第一』を最優先の方針として掲げている。','회사는 ''안전 제일''을 최우선 방침으로 내세우고 있다.'),
('n1-0377','2026-10-04','無用','むよう','무용; 불필요; 쓸모없음','必要がないこと、または役に立たないこと。『心配無用』のように使う。','この装置は自動で停止するため、異常時に利用者が操作する必要はなく、心配は無用だ。','이 장치는 자동으로 정지하므로 이상 시 이용자가 조작할 필요가 없어 걱정할 필요가 없다.'),
('n1-0166','2026-10-04','判決','はんけつ','판결','裁判所が訴訟について事実と法律に基づいて判断を示すこと。また、その判断。','裁判所は双方の主張と証拠を検討した上で、来月判決を言い渡す予定だ。','법원은 양측의 주장과 증거를 검토한 뒤 다음 달 판결을 선고할 예정이다.'),
('n1-0169','2026-10-04','武装','ぶそう','무장','武器や防具など、戦闘に必要な装備を身につけたり備えたりすること。また、その装備。','武装した集団が国境付近に現れたため、周辺地域の警戒が強化された。','무장한 집단이 국경 부근에 나타나 주변 지역의 경계가 강화되었다.'),
('n1-1138','2026-10-04','営む','いとなむ','영위하다; 운영하다; 치르다','生活・商売・事業などを続けて行う。また、儀式などを執り行う。','祖父はこの町で長年、小さな商店を営んできた。','할아버지는 이 마을에서 오랫동안 작은 상점을 운영해 왔다.'),
('n1-0171','2026-10-04','同盟','どうめい','동맹','共通の目的や利益のために、複数の国・団体・個人などが協力関係を結ぶこと。また、その関係。','両国は安全保障上の協力を強化するため、新たな同盟関係を結んだ。','두 나라는 안보 협력을 강화하기 위해 새로운 동맹 관계를 맺었다.'),
('n1-0412','2026-10-04','誠実','せいじつ','성실; 진실됨; 성의 있음','人や物事に対して、うそやごまかしがなく真心を持って向き合うこと。','問題が起きたときほど、事実を隠さず誠実に説明する姿勢が信頼につながる。','문제가 생겼을 때일수록 사실을 숨기지 않고 성실하게 설명하는 태도가 신뢰로 이어진다.'),
('n1-0173','2026-10-04','形態','けいたい','형태; 형식','物事が一定の構造や機能をもって現れている具体的な形やあり方。','働き方の多様化に伴い、雇用の形態も以前より複雑になっている。','근무 방식의 다양화에 따라 고용 형태도 이전보다 복잡해지고 있다.'),
('n1-0174','2026-10-04','権限','けんげん','권한','職務や立場に基づいて、判断・命令・処理などを行うことのできる範囲や権利。','この金額を超える契約は、部長の権限だけでは承認できない。','이 금액을 넘는 계약은 부장의 권한만으로는 승인할 수 없다.'),
('n1-1185','2026-10-04','携わる','たずさわる','종사하다; 관여하다','仕事・研究・事業などに関係して、その活動に参加する。','長年、金融システムの開発に携わってきた。','오랫동안 금융 시스템 개발에 종사해 왔다.'),
('n1-0417','2026-10-04','大胆','だいたん','대담; 과감','恐れずに思い切って行動するさま。また、発想や変更の規模が大きいさま。','業績を立て直すためには、従来の仕組みにこだわらない大胆な改革が必要だ。','실적을 회복하려면 기존 구조에 얽매이지 않는 대담한 개혁이 필요하다.'),
('n1-0176','2026-10-04','入手','にゅうしゅ','입수; 획득','必要な物や情報などを手に入れること。','公開前の資料を不正に入手した疑いで、関係者への聞き取りが行われた。','공개 전 자료를 부정하게 입수한 의혹으로 관계자에 대한 조사가 이루어졌다.'),
('n1-0177','2026-10-04','権威','けんい','권위; 권위자','専門的な知識・実績・地位などによって、他者から高い信頼や影響力を認められていること。また、その人や機関。','その研究者はこの分野の権威として、国際的にも高く評価されている。','그 연구자는 이 분야의 권위자로서 국제적으로도 높이 평가받고 있다.'),
('n1-1386','2026-10-04','免れる','まぬかれる','면하다; 모면하다; 벗어나다','好ましくない責任・処罰・危険・被害などを受けずに済む。','早めに避難したため、住民の多くは大きな被害を免れた。','일찍 대피했기 때문에 주민 대부분은 큰 피해를 면했다.'),
('n1-0178','2026-10-04','証言','しょうげん','증언','見聞きした事実について述べ、その内容を証明するための発言をすること。また、その発言。','目撃者の証言と防犯カメラの映像には、一部食い違いがあった。','목격자의 증언과 방범 카메라 영상에는 일부 불일치가 있었다.'),
('n1-0436','2026-10-04','無効','むこう','무효; 효력이 없음','法律・契約・投票・設定などに効力や効果がないこと。','期限を過ぎた申請は無効となるため、締切日を必ず確認してください。','기한이 지난 신청은 무효가 되므로 마감일을 반드시 확인해 주세요.'),
('n1-0179','2026-10-04','措置','そち','조치; 대책','ある事態や問題に対応するため、必要な手段や処理を講じること。また、その手段。','個人情報の流出が確認され、会社は直ちにアクセスを停止する措置を取った。','개인정보 유출이 확인되어 회사는 즉시 접근을 중지하는 조치를 취했다.'),
('n1-0180','2026-10-04','悪化','あっか','악화','状態・状況・関係・症状などが以前より悪くなること。','資金繰りがさらに悪化すれば、事業の継続そのものが難しくなる。','자금 사정이 더 악화되면 사업을 계속하는 것 자체가 어려워진다.'),
('n1-0181','2026-10-04','総合','そうごう','종합; 통합','複数の要素や観点をまとめて一つの全体として扱うこと。','価格だけでなく、安全性や使いやすさも含めて総合的に評価する必要がある。','가격뿐 아니라 안전성과 사용 편의성도 포함해 종합적으로 평가할 필요가 있다.');
INSERT INTO _n1_b1_words_0099(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0182','2026-10-05','対抗','たいこう','대항; 맞서 경쟁함','相手に負けないように、同じ立場で張り合ったり抵抗したりすること。','海外企業に対抗するため、国内各社は共同で新技術の開発を進めている。','해외 기업에 대항하기 위해 국내 각 사는 공동으로 신기술 개발을 추진하고 있다.'),
('n1-1398','2026-10-05','募る','つのる','모집하다; 모으다; 점점 심해지다','人・作品・寄付などを広く呼びかけて集める。また、不安・期待・思いなどの程度がますます強くなる。','会社は社内から新規事業のアイデアを募っている。','회사는 사내에서 신규 사업 아이디어를 모집하고 있다.'),
('n1-0456','2026-10-05','不当','ふとう','부당; 정당하지 않음','道理・法律・公平性などに照らして正当ではないこと。','不当な理由で契約を解除されたとして、会社を相手に訴訟を起こした。','부당한 이유로 계약이 해지되었다며 회사를 상대로 소송을 제기했다.'),
('n1-0183','2026-10-05','回収','かいしゅう','회수; 수거','配布・貸与・販売した物などを再び集めて取り戻すこと。代金や資金を取り戻す場合にもいう。','製品に不具合が見つかり、メーカーは対象商品を自主回収すると発表した。','제품에서 결함이 발견되어 제조사는 해당 상품을 자진 회수한다고 발표했다.'),
('n1-0186','2026-10-05','作用','さよう','작용; 영향','あるものが別のものに働きかけ、変化や効果を生じさせること。また、その働き。','この薬には炎症を抑える作用があるが、副作用にも注意が必要だ。','이 약에는 염증을 억제하는 작용이 있지만 부작용에도 주의가 필요하다.'),
('n1-1494','2026-10-05','脅かす','おどかす','겁주다; 위협하다','相手が怖がるような言葉・行動をして驚かせたり恐れさせたりする。','冗談のつもりでも、相手を脅かすような発言は避けるべきだ。','농담이라고 해도 상대를 겁주는 발언은 피해야 한다.'),
('n1-0189','2026-10-05','抗議','こうぎ','항의','不当だと考える行為や決定に対して、反対や不満の意思を明確に示すこと。','住民は突然の計画変更に抗議し、自治体に説明を求めた。','주민들은 갑작스러운 계획 변경에 항의하며 지자체에 설명을 요구했다.'),
('n1-0472','2026-10-05','率直','そっちょく','솔직; 거리낌 없음','自分の考えや気持ちを飾ったり隠したりせず、そのまま表すさま。','改善につなげたいので、この企画について率直な意見を聞かせてください。','개선에 반영하고 싶으니 이 기획에 대한 솔직한 의견을 들려주세요.'),
('n1-0190','2026-10-05','記載','きさい','기재; 기록','必要な事柄を文書・書類・ウェブページなどに書いて載せること。','申請内容に誤りがないか、記載事項を提出前にもう一度確認してください。','신청 내용에 오류가 없는지 기재 사항을 제출 전에 다시 한번 확인해 주세요.'),
('n1-0193','2026-10-05','再生','さいせい','재생; 재생시키기; 회복','失われたり衰えたりしたものを再び生かすこと。また、録音・録画した音声や映像を機器で再び出すこと。','動画が正常に再生できない場合は、通信環境を確認してください。','동영상이 정상적으로 재생되지 않을 경우 통신 환경을 확인해 주세요.'),
('n1-1808','2026-10-05','率いる','ひきいる','이끌다; 거느리다; 지휘하다','集団・組織・部下などの先頭に立って統率し、導く。','彼女は二十人の開発チームを率いて、大規模な移行プロジェクトを完了させた。','그녀는 20명의 개발팀을 이끌어 대규모 이행 프로젝트를 완료했다.'),
('n1-0528','2026-10-05','果たして','はたして','과연; 정말; 도대체','予想どおりの結果になったことを示す語。また、疑問文で『本当に〜だろうか』という強い疑いを表す。','新しい制度は、果たして現場の負担を本当に減らすことができるのだろうか。','새 제도는 과연 현장의 부담을 정말 줄일 수 있을까.'),
('n1-0194','2026-10-05','本能','ほんのう','본능','学習や経験によらず、生物が生まれつき備えている行動の傾向や能力。','危険を感じた瞬間、考えるより先に身を引いたのは本能的な反応だった。','위험을 느낀 순간 생각하기도 전에 몸을 피한 것은 본능적인 반응이었다.'),
('n1-0195','2026-10-05','追放','ついほう','추방; 축출','人をある国・地域・組織・集団などから強制的に追い出すこと。','規則に重大な違反をしたとして、彼は組織から追放された。','규정을 중대하게 위반했다는 이유로 그는 조직에서 추방되었다.'),
('n1-1897','2026-10-05','促す','うながす','촉구하다; 재촉하다; 촉진하다; 권하다','相手に行動するよう働きかける。また、物事の進行・発達・変化を早める。','司会者は時間が限られているため、発言を簡潔にまとめるよう参加者に促した。','사회자는 시간이 한정되어 있어 발언을 간결하게 정리해 달라고 참가자들에게 촉구했다.'),
('n1-0196','2026-10-05','減少','げんしょう','감소','数量・程度・割合などが少なくなること。','少子化の影響で、地域の児童数は十年前と比べて大幅に減少した。','저출산의 영향으로 지역 아동 수는 10년 전과 비교해 크게 감소했다.'),
('n1-1089','2026-10-05','極端','きょくたん','극단; 극단적임','考え・状態・程度などが一方に大きく偏っているさま。','一つの事例だけを見て極端な結論を出すのは危険だ。','한 가지 사례만 보고 극단적인 결론을 내리는 것은 위험하다.'),
('n1-0197','2026-10-05','雇用','こよう','고용','賃金を支払うことを条件に、人を仕事に就かせること。また、その労働関係。','景気の回復に伴い、企業の雇用意欲も徐々に高まっている。','경기 회복에 따라 기업의 고용 의욕도 점차 높아지고 있다.'),
('n1-0198','2026-10-05','協議','きょうぎ','협의; 논의','関係する複数の人や組織が、結論や方針を決めるために話し合うこと。','詳細な条件については、両社で引き続き協議することになった。','상세 조건에 대해서는 양사가 계속 협의하기로 했다.'),
('n1-0199','2026-10-05','領域','りょういき','영역; 분야','一定の範囲をもつ地域・分野・活動範囲。国の主権が及ぶ範囲を指す場合もある。','人工知能は、これまで人間にしかできないと考えられていた領域にも広がっている。','인공지능은 지금까지 인간만 할 수 있다고 여겨졌던 영역으로도 확산되고 있다.'),
('n1-0200','2026-10-06','推測','すいそく','추측; 추정','分かっている事実や状況を手がかりに、まだ明らかでないことを推し量ること。','証拠が十分でない段階で、原因を推測だけで断定するべきではない。','증거가 충분하지 않은 단계에서 원인을 추측만으로 단정해서는 안 된다.'),
('n1-1914','2026-10-06','踏まえる','ふまえる','근거로 삼다; 고려하다; 바탕으로 하다','事実・経験・意見などを根拠や前提として、その上で判断・行動する。','利用者から寄せられた意見を踏まえて、次期版の仕様を見直した。','이용자에게서 받은 의견을 바탕으로 다음 버전의 사양을 재검토했다.'),
('n1-1112','2026-10-06','厳密','げんみつ','엄밀함; 정확하고 빈틈없음','細部まで基準・定義・手順に従い、少しのあいまいさも許さないさま。','研究結果を比較するには、条件を厳密にそろえる必要がある。','연구 결과를 비교하려면 조건을 엄밀하게 맞출 필요가 있다.'),
('n1-0201','2026-10-06','反乱','はんらん','반란; 반역','政府・支配者・組織の指導部などに対して、集団で武力や行動を起こして反抗すること。','軍の一部が政府に対して反乱を起こし、首都では緊張が高まった。','군 일부가 정부에 반란을 일으켜 수도의 긴장이 고조되었다.'),
('n1-0203','2026-10-06','推進','すいしん','추진; 촉진','計画・政策・事業などが前に進むよう積極的に進めること。また、物体を前方へ進ませること。','政府は行政手続のデジタル化をさらに推進する方針を示した。','정부는 행정 절차의 디지털화를 더욱 추진하겠다는 방침을 밝혔다.'),
('n1-2010','2026-10-06','制する','せいする','제압하다; 통제하다; 억제하다','相手・状況などを抑えて自分の支配下に置く。','終盤に得点を重ねて試合を制した。','후반에 득점을 거듭해 경기를 제압했다.'),
('n1-0204','2026-10-06','農地','のうち','농지; 농경지','田畑など、農業のために利用される土地。','人口減少に伴って使われなくなった農地をどう活用するかが課題になっている。','인구 감소에 따라 사용되지 않게 된 농지를 어떻게 활용할지가 과제가 되고 있다.'),
('n1-1127','2026-10-06','乏しい','とぼしい','부족하다; 빈약하다','必要な量・内容・経験・資源などが十分にない。','経験が乏しい段階では、判断を急がず周囲に確認した方がよい。','경험이 부족한 단계에서는 판단을 서두르지 말고 주변에 확인하는 편이 좋다.'),
('n1-0207','2026-10-06','掲載','けいさい','게재; 싣기','文章・写真・情報などを新聞・雑誌・ウェブサイトなどに載せること。','募集要項の詳細は、来週公式サイトに掲載される予定だ。','모집 요강의 상세 내용은 다음 주 공식 사이트에 게재될 예정이다.'),
('n1-0208','2026-10-06','進化','しんか','진화; 발전','生物が世代を重ねる中で変化すること。また、技術や制度などが段階的に発展すること。','生成AIの急速な進化によって、業務の進め方そのものが変わり始めている。','생성형 AI의 빠른 진화로 업무 진행 방식 자체가 변하기 시작하고 있다.'),
('n1-2151','2026-10-06','阻む','はばむ','가로막다; 방해하다; 저지하다','進行・実現などを妨げて止める。','大雪が救助隊の進行を阻んだ。','폭설이 구조대의 진행을 가로막았다.'),
('n1-1244','2026-10-06','無論','むろん','물론; 말할 것도 없이','改めて言うまでもなく、当然。','安全性は無論、使いやすさも重視して設計する必要がある。','안전성은 물론 사용 편의성도 중시해 설계할 필요가 있다.'),
('n1-0209','2026-10-06','国境','くにざかい','국경; 나라 사이의 경계','国と国との領土を分ける境界。『こっきょう』とも読む。','国境を越えて移動する人や物の流れは、政治情勢によって大きく変化する。','국경을 넘어 이동하는 사람과 물자의 흐름은 정치 정세에 따라 크게 변한다.'),
('n1-0210','2026-10-06','圧力','あつりょく','압력; 압박','物理的に押す力。また、人や組織に特定の行動を取らせようとする強い働きかけ。','外部からの圧力に左右されず、客観的な基準で判断することが求められる。','외부 압력에 좌우되지 않고 객관적인 기준으로 판단하는 것이 요구된다.'),
('n1-2179','2026-10-06','覆す','くつがえす','뒤집다; 번복하다; 전복하다','それまでの考え・決定・制度などを根本から変える。物をひっくり返す意味でも使う。','新しい証拠が従来の説を覆した。','새로운 증거가 기존 학설을 뒤집었다.'),
('n1-0211','2026-10-06','決断','けつだん','결단; 결정','重要な問題について十分に考えた上で、最終的に方針や行動を決めること。','情報が完全にそろうのを待てない状況では、責任者の素早い決断が必要になる。','정보가 완전히 갖춰지기를 기다릴 수 없는 상황에서는 책임자의 빠른 결단이 필요하다.'),
('n1-1274','2026-10-06','緩やか','ゆるやか','완만함; 느슨함; 부드러움','傾き・変化・速度・規制などが急ではなく、穏やかであるさま。','景気は急回復ではなく、緩やかな改善を続けている。','경기는 급회복이 아니라 완만한 개선을 이어가고 있다.'),
('n1-0212','2026-10-06','大衆','たいしゅう','대중; 일반 대중','社会を構成する多数の一般の人々。','専門的だった技術が低価格化によって大衆にも広く普及した。','전문적이던 기술이 저가화되면서 일반 대중에게도 널리 보급되었다.'),
('n1-0213','2026-10-06','警戒','けいかい','경계; 주의','危険・事故・攻撃などに備えて、周囲の状況に十分注意すること。','台風の接近に伴い、自治体は土砂災害への警戒を呼びかけている。','태풍 접근에 따라 지자체는 산사태에 대한 경계를 당부하고 있다.'),
('n1-0214','2026-10-06','人材','じんざい','인재; 인력','組織や社会で役立つ能力・知識・経験などを備えた人。また、仕事を担う人員。','高度なIT人材を確保するため、企業間の採用競争が激しくなっている。','고급 IT 인재를 확보하기 위해 기업 간 채용 경쟁이 치열해지고 있다.');
INSERT INTO _n1_b1_words_0099(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0215','2026-10-07','確信','かくしん','확신','ある判断や考えが正しいと強く信じ、疑わないこと。また、その気持ち。','何度も検証を重ねた結果、この仮説は正しいという確信を持つようになった。','여러 차례 검증을 거친 결과 이 가설이 옳다는 확신을 갖게 되었다.'),
('n1-2191','2026-10-07','顧みる','かえりみる','돌아보다; 돌이켜보다; 돌보다','過去を振り返って考える。また、周囲や人のことを気にかける。','これまでの行動を顧みて反省した。','지금까지의 행동을 돌아보며 반성했다.'),
('n1-1441','2026-10-07','大概','たいがい','대개; 대부분; 적당한 정도','ほとんど・たいてい。また、『大概にする』の形で、度を越さず適当なところでやめる意にも使う。','この種のトラブルは大概、設定の見落としが原因になっている。','이런 종류의 문제는 대개 설정 누락이 원인이 되고 있다.'),
('n1-0216','2026-10-07','向上','こうじょう','향상; 제고','能力・技術・品質・水準などが以前より高くなること。また、高くすること。','サービス品質の向上には、利用者からの意見を継続的に分析することが欠かせない。','서비스 품질 향상을 위해서는 이용자 의견을 지속적으로 분석하는 것이 필수적이다.'),
('n1-0217','2026-10-07','会見','かいけん','회견; 공식 면담','公的な立場の人などが記者や関係者と会い、説明や質疑応答を行うこと。また、その場。','社長は記者会見を開き、今回の不祥事について謝罪した。','사장은 기자회견을 열어 이번 불상사에 대해 사과했다.'),
('n1-2206','2026-10-07','慎む','つつしむ','삼가다; 조심하다; 절제하다','言動を控えめにし、注意深く行動する。また、ある行為を控える。','式典では私語を慎んでください。','식전에서는 사적인 대화를 삼가 주세요.'),
('n1-0221','2026-10-07','接触','せっしょく','접촉; 접촉함','物と物が触れ合うこと。また、人・組織などが会ったり連絡を取ったりして関係を持つこと。','感染経路を調べるため、患者と接触した人の行動履歴が確認された。','감염 경로를 조사하기 위해 환자와 접촉한 사람들의 행동 이력이 확인되었다.'),
('n1-1906','2026-10-07','著しい','いちじるしい','현저하다; 두드러지다; 눈에 띄게 크다','変化・差・進歩などが、誰の目にも分かるほどはっきりしている。','新しい設備を導入してから、生産効率に著しい改善が見られた。','새 설비를 도입한 뒤 생산 효율에서 현저한 개선이 나타났다.'),
('n1-0225','2026-10-07','根本','こんぽん','근본; 근원; 기초','物事を成り立たせている最も基本的な部分や原因。','表面的な修正だけではなく、問題の根本にある業務設計そのものを見直す必要がある。','표면적인 수정만이 아니라 문제의 근본에 있는 업무 설계 자체를 재검토할 필요가 있다.'),
('n1-0226','2026-10-07','実質','じっしつ','실질; 실제 내용','形式や名目ではなく、実際に中身を成している内容や状態。','制度上は任意とされているが、実質的には全員の参加が求められている。','제도상으로는 임의이지만 실질적으로는 전원의 참가가 요구되고 있다.'),
('n1-2213','2026-10-07','脅す','おどす','위협하다; 협박하다; 겁주다','怖い言葉・態度などで相手に恐怖を与え、従わせようとする。','金を出せと相手を脅した。','돈을 내놓으라고 상대를 위협했다.'),
('n1-1953','2026-10-07','敢えて','あえて','굳이; 감히; 일부러','困難・反対・必要性の低さなどを承知のうえで、それでも意図的に行うさま。','問題点を明確にするため、会議ではあえて厳しい意見を述べた。','문제점을 분명히 하기 위해 회의에서 굳이 엄격한 의견을 말했다.'),
('n1-0228','2026-10-07','運用','うんよう','운용; 운영','制度・システム・資金などを目的に沿って実際に使い、管理すること。','システムを導入するだけでなく、現場で無理なく運用できる体制を整える必要がある。','시스템을 도입하는 것뿐 아니라 현장에서 무리 없이 운용할 수 있는 체계를 갖출 필요가 있다.'),
('n1-0229','2026-10-07','統治','とうじ','통치; 지배','国家や地域を政治的な権力によって治め、秩序を維持すること。','植民地統治の歴史は、現在の社会構造にも大きな影響を残している。','식민지 통치의 역사는 현재의 사회 구조에도 큰 영향을 남기고 있다.'),
('n1-2218','2026-10-07','逸らす','そらす','돌리다; 피하다; 비껴가게 하다','視線・注意・方向などを別のほうへ向ける。','質問されると彼は視線を逸らした。','질문을 받자 그는 시선을 돌렸다.'),
('n1-0231','2026-10-07','流通','りゅうつう','유통; 순환','商品・貨幣・情報などが社会の中で移動し、広く行き渡ること。特に商品が生産者から消費者へ渡る過程をいう。','物流網の混乱によって、一部の商品が市場に十分流通しない状態が続いた。','물류망 혼란으로 일부 상품이 시장에 충분히 유통되지 않는 상태가 이어졌다.'),
('n1-1997','2026-10-07','勇敢','ゆうかん','용감함; 용감하다','危険や困難を恐れず、勇気をもって行動するさま。','彼の勇敢な行動によって多くの人が助かった。','그의 용감한 행동으로 많은 사람이 도움을 받았다.'),
('n1-0234','2026-10-07','余地','よち','여지; 가능성; 여유 공간','何かを行ったり変えたりすることのできる可能性や余裕。','現行案にも改善の余地はあるため、利用者の意見を反映して修正する予定だ。','현행안에도 개선의 여지가 있어 이용자 의견을 반영해 수정할 예정이다.'),
('n1-0235','2026-10-07','品質','ひんしつ','품질','製品やサービスなどが持つ性質や性能の良し悪しを表す程度。','大量生産に移行しても、品質を一定に保つための検査体制が必要だ。','대량생산으로 전환해도 품질을 일정하게 유지하기 위한 검사 체계가 필요하다.'),
('n1-0239','2026-10-07','宣言','せんげん','선언; 공표','自分や組織の立場・方針・意思などを公に明確に表明すること。','市は二〇五〇年までに温室効果ガスの排出を実質ゼロにすると宣言した。','시는 2050년까지 온실가스 배출을 실질적으로 제로로 만들겠다고 선언했다.'),
('n1-0240','2026-10-08','合意','ごうい','합의; 의견 일치','複数の当事者の意見や意思が一致し、共通の結論を受け入れること。','長時間の交渉の末、双方は基本条件について合意に達した。','장시간의 협상 끝에 양측은 기본 조건에 대해 합의에 도달했다.'),
('n1-2228','2026-10-08','躊躇う','ためらう','망설이다; 주저하다','決心がつかず、行動するのを迷う。','彼は答えるのを少しためらった。','그는 대답하기를 조금 망설였다.'),
('n1-2105','2026-10-08','疎か','おろそか','소홀함; 등한함','大切に扱わず、注意・努力が十分でないさま。','忙しくても安全確認を疎かにしてはいけない。','바빠도 안전 확인을 소홀히 해서는 안 된다.'),
('n1-0241','2026-10-08','論理','ろんり','논리','考えや主張を筋道立てて結び付け、結論へ導くための考え方や原理。','結論だけでなく、そこに至る論理を明確に説明しなければ相手は納得しない。','결론뿐 아니라 그 결론에 이르는 논리를 명확히 설명하지 않으면 상대는 납득하지 않는다.'),
('n1-0246','2026-10-08','審査','しんさ','심사; 검토','一定の基準に照らして、資格・内容・優劣などを詳しく調べて判断すること。','書類審査を通過した応募者だけが、次の面接に進むことができる。','서류 심사를 통과한 지원자만 다음 면접으로 진행할 수 있다.'),
('n1-2323','2026-10-08','緩む','ゆるむ','느슨해지다; 풀리다; 완화되다','締まっていたものがゆるくなる。また、緊張・規律などが弱くなる。','長く使っているうちに、ねじが少し緩んできた。','오랫동안 사용하다 보니 나사가 조금 느슨해졌다.'),
('n1-0247','2026-10-08','保管','ほかん','보관; 보존','物や資料などを安全な状態で預かり、必要になるまで保存しておくこと。','契約書の原本は、規定に従って施錠できる場所に保管してください。','계약서 원본은 규정에 따라 잠글 수 있는 장소에 보관해 주세요.'),
('n1-2154','2026-10-08','甚だ','はなはだ','매우; 몹시; 심히','程度が普通を大きく超えているさま。非常に。','その説明は甚だ不十分だ。','그 설명은 매우 불충분하다.'),
('n1-0249','2026-10-08','一連','いちれん','일련; 연속된 한 묶음','互いに関係しながら続いている一つのまとまりや流れ。','会社は一連の不祥事について調査結果を公表し、再発防止策を示した。','회사는 일련의 불상사에 대한 조사 결과를 발표하고 재발 방지책을 제시했다.'),
('n1-0251','2026-10-08','人格','じんかく','인격; 인품','一人の人間として備わっている性格・品性・尊厳などを総合したもの。','仕事の能力が高くても、他人の人格を否定するような発言は許されない。','업무 능력이 뛰어나더라도 다른 사람의 인격을 부정하는 발언은 용납될 수 없다.'),
('n1-2324','2026-10-08','緩める','ゆるめる','느슨하게 하다; 늦추다; 완화하다; 풀다','締まっているものをゆるくする。また、速度・緊張・規制などを弱める。','苦しくなったので、ネクタイを少し緩めた。','답답해져서 넥타이를 조금 느슨하게 풀었다.'),
('n1-2192','2026-10-08','脆い','もろい','부서지기 쉽다; 약하다; 여리다','壊れやすく丈夫でない。また、精神的に弱い。','この素材は軽いが衝撃には脆い。','이 소재는 가볍지만 충격에는 약하다.'),
('n1-0252','2026-10-08','証人','しょうにん','증인','事実について知っていることを述べたり、その事実を証明したりする人。','裁判では複数の証人が出廷し、事件当日の状況について証言した。','재판에서는 여러 증인이 출석해 사건 당일의 상황에 대해 증언했다.'),
('n1-0254','2026-10-08','福祉','ふくし','복지','人々が安心して健康で文化的な生活を送れるよう、社会が生活や自立を支えること。また、その制度や施策。','高齢者福祉を充実させるには、介護人材の確保も大きな課題となる。','노인 복지를 충실하게 하려면 요양 인력을 확보하는 것도 큰 과제가 된다.'),
('n1-2494','2026-10-08','準ずる','じゅんずる','준하다; 기준에 따르다; 그에 상응하다','ある基準・例に従う。また、それに相当する扱いをする。','契約社員にも正社員に準ずる制度を適用する。','계약직에게도 정규직에 준하는 제도를 적용한다.'),
('n1-0255','2026-10-08','決意','けつい','결의; 결심','あることを必ず行うと心を固く決めること。また、その強い意志。','失敗をきっかけに基礎から学び直すことを決意し、毎日勉強を続けている。','실패를 계기로 기초부터 다시 배우기로 결심하고 매일 공부를 계속하고 있다.'),
('n1-2357','2026-10-08','厳か','おごそか','엄숙하다; 장엄하다; 위엄 있다','重々しく、威厳があり、身が引き締まるような雰囲気であるさま。','式典は厳かな雰囲気の中で行われた。','식전은 엄숙한 분위기 속에서 진행됐다.'),
('n1-0256','2026-10-08','解除','かいじょ','해제; 해지; 취소','制限・契約・警報・設定など、それまで有効だった状態や拘束を取り除くこと。','安全が確認されたため、避難指示は午後三時に解除された。','안전이 확인되어 대피 지시는 오후 3시에 해제되었다.'),
('n1-0257','2026-10-08','職務','しょくむ','직무; 맡은 업무','職業上の地位や役割に基づいて、責任を持って行うべき仕事。','職務上知り得た個人情報を、私的な目的で利用してはならない。','직무상 알게 된 개인정보를 사적인 목적으로 이용해서는 안 된다.'),
('n1-0260','2026-10-08','転換','てんかん','전환; 변환','方針・状態・考え方・方向などを別のものへ切り替えること。','会社は大量生産中心の方針から、高付加価値商品の開発へ転換した。','회사는 대량생산 중심 방침에서 고부가가치 상품 개발로 전환했다.');
INSERT INTO _n1_b1_words_0099(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0261','2026-10-09','資産','しさん','자산; 재산','個人や法人が所有し、経済的な価値を持つ財産や権利。','企業価値を判断する際は、売上だけでなく保有する資産や負債も確認する必要がある。','기업 가치를 판단할 때는 매출뿐 아니라 보유 자산과 부채도 확인할 필요가 있다.'),
('n1-2534','2026-10-09','慕う','したう','사모하다; 흠모하다; 그리워하다; 따르다','恋しく思う。また、尊敬・好意を持ってその人について行こうとする。','多くの弟子がその先生を慕って集まった。','많은 제자가 그 선생님을 흠모해 모였다.'),
('n1-2366','2026-10-09','一概に','いちがいに','일률적으로; 무조건; 단정적으로','事情の違いを考えず、すべて同じように決めつけるさま。','経験年数だけで能力を一概に判断することはできない。','경력 연수만으로 능력을 일률적으로 판단할 수는 없다.'),
('n1-0262','2026-10-09','経過','けいか','경과; 진행 과정; 시간의 흐름','時間が過ぎること。また、物事が進んでいく途中の過程や成り行き。','手術後の経過は良好で、問題がなければ来週退院できる見込みだ。','수술 후 경과는 양호하여 문제가 없으면 다음 주 퇴원할 전망이다.'),
('n1-0266','2026-10-09','施行','しぎょう','시행; 실시','法令・制度・命令などを実際に行い、効力を生じさせること。現代では『しこう』と読むのが一般的で、『しぎょう』も辞書に認められる読み。','改正された制度は来年四月から施行される予定で、関係機関が準備を進めている。','개정된 제도는 내년 4월부터 시행될 예정이며 관계 기관이 준비를 진행하고 있다.'),
('n1-2618','2026-10-09','誤魔化す','ごまかす','속이다; 얼버무리다; 속여 넘기다','事実を隠したり、話をそらしたりして相手を欺く。','質問の核心を誤魔化さずに答えてください。','질문의 핵심을 얼버무리지 말고 대답해 주세요.'),
('n1-0267','2026-10-09','要因','よういん','요인; 원인 요소','ある結果や現象を生じさせる重要な原因・条件。','離職率が上がった要因を特定するため、社員への匿名調査を実施した。','이직률이 오른 요인을 특정하기 위해 직원 대상 익명 조사를 실시했다.'),
('n1-2396','2026-10-09','軽率','けいそつ','경솔함; 신중하지 못함','よく考えず、言動が軽く慎重さに欠けること。','軽率な発言で相手を傷つけてしまった。','경솔한 발언으로 상대에게 상처를 주고 말았다.'),
('n1-0270','2026-10-09','報酬','ほうしゅう','보수; 대가; 사례','仕事・労働・サービス・成果などに対する対価として受け取る金銭や物。','成果に応じて報酬が決まる制度には、評価基準の透明性が欠かせない。','성과에 따라 보수가 결정되는 제도에는 평가 기준의 투명성이 필수적이다.'),
('n1-0271','2026-10-09','側面','そくめん','측면; 일면; 옆면','物の横の面。また、物事をある立場や角度から見た一つの面。','便利さという側面だけでなく、個人情報保護の観点からもサービスを評価する必要がある。','편리함이라는 측면뿐 아니라 개인정보 보호 관점에서도 서비스를 평가할 필요가 있다.'),
('n1-2675','2026-10-09','紛れる','まぎれる','뒤섞이다; 구별하기 어려워지다; 다른 데 정신이 팔리다','他のものに混じって見分けにくくなる。また、別のことに気を取られて気がまぎれる。','人混みに紛れて姿が見えなくなった。','인파에 섞여 모습이 보이지 않게 됐다.'),
('n1-2639','2026-10-09','先天的','せんてんてき','선천적','生まれつき備わっているさま。','その特徴には先天的な要因も関係している。','그 특징에는 선천적인 요인도 관련되어 있다.'),
('n1-0272','2026-10-09','独占','どくせん','독점','特定の人・企業・組織などが、利益・市場・権利などを一人または一社で占めること。','一社が市場を独占すると、価格競争が働きにくくなるおそれがある。','한 회사가 시장을 독점하면 가격 경쟁이 작동하기 어려워질 우려가 있다.'),
('n1-0273','2026-10-09','観点','かんてん','관점; 보는 입장','物事を見たり判断したりするときの立場や着目する点。','コストの観点では有利だが、長期的な安全性については追加検証が必要だ。','비용 관점에서는 유리하지만 장기적인 안전성에 대해서는 추가 검증이 필요하다.'),
('n1-2722','2026-10-09','膨れる','ふくれる','부풀다; 붓다; 토라지다','体積が増えてふくらむ。また、不満でふくれっ面になる。','風船が空気で大きく膨れた。','풍선이 공기로 크게 부풀었다.'),
('n1-0274','2026-10-09','実践','じっせん','실천; 실행','理論・方針・計画として考えたことを、実際の行動に移して行うこと。','研修で学んだ知識は、実際の業務で実践して初めて身につく。','연수에서 배운 지식은 실제 업무에서 실천해 봐야 비로소 익숙해진다.'),
('n1-2650','2026-10-09','紛らわしい','まぎらわしい','헷갈리기 쉽다; 혼동하기 쉽다; 애매하다','似ていて区別しにくく、間違えやすい。','この二つの名前は紛らわしいので注意が必要だ。','이 두 이름은 헷갈리기 쉬워 주의가 필요하다.'),
('n1-0275','2026-10-09','依存','いそん','의존; 의지함','自分だけでは成り立たず、他の人・物・制度などを頼りにすること。『いぞん』とも読む。','一つの取引先に依存しすぎると、その会社の事情で経営が大きく左右される。','한 거래처에 지나치게 의존하면 그 회사의 사정에 따라 경영이 크게 좌우된다.'),
('n1-0277','2026-10-09','開拓','かいたく','개척; 개간','荒地を切り開いて利用できるようにすること。また、新しい分野・市場・進路などを切り開くこと。','国内需要が伸び悩む中、会社は新たな海外市場の開拓を急いでいる。','국내 수요가 정체된 가운데 회사는 새로운 해외 시장 개척을 서두르고 있다.'),
('n1-0278','2026-10-09','協定','きょうてい','협정; 합의 사항','国・団体・組織などの当事者が話し合い、一定の事項について取り決めること。また、その取り決め。','両国は貿易手続きを簡素化するため、新しい経済協定に署名した。','양국은 무역 절차를 간소화하기 위해 새로운 경제 협정에 서명했다.'),
('n1-0279','2026-10-10','本格','ほんかく','본격; 정통; 제대로 된 수준','本来の方式・内容を備えていること。また、仮の段階ではなく本腰を入れて進める状態。','試験運用で大きな問題がなかったため、来月から本格的な導入を始める。','시험 운용에서 큰 문제가 없었기 때문에 다음 달부터 본격적인 도입을 시작한다.'),
('n1-2733','2026-10-10','隔たる','へだたる','떨어져 있다; 차이가 나다; 동떨어지다','距離・時間・考えなどが大きく離れている。','二つの町は山を挟んで大きく隔たっている。','두 마을은 산을 사이에 두고 크게 떨어져 있다.'),
('n1-2815','2026-10-10','動的','どうてき','동적; 역동적','動きや変化を伴うさま。','この画面は利用者の操作に応じて動的に変化する。','이 화면은 사용자의 조작에 따라 동적으로 변한다.'),
('n1-0281','2026-10-10','視点','してん','시점; 관점; 보는 입장','物事を見たり考えたり判断したりするときの立場や着目する位置。','利用者の視点に立つと、機能の多さより操作の分かりやすさのほうが重要かもしれない。','이용자의 관점에서 보면 기능의 많고 적음보다 조작의 이해하기 쉬움이 더 중요할 수 있다.'),
('n1-0282','2026-10-10','演出','えんしゅつ','연출; 효과적으로 꾸밈','映画・舞台・番組などで作品全体の表現を組み立て指揮すること。また、場面や印象を意図的に作り出すこと。','照明と音楽の演出によって、同じ会場でもまったく違う雰囲気が生まれた。','조명과 음악 연출을 통해 같은 행사장에서도 전혀 다른 분위기가 만들어졌다.'),
('n1-2895','2026-10-10','準じる','じゅんじる','준하다; 따르다; 적용하다','ある基準・例に従う。また、それと同様に扱う。','待遇は正社員に準じる。','대우는 정규직에 준한다.'),
('n1-0284','2026-10-10','動機','どうき','동기; 계기','人がある行動を起こす直接的な理由やきっかけ。','応募した動機を聞かれたら、仕事内容と自分の経験を結び付けて説明するとよい。','지원 동기를 질문받으면 업무 내용과 자신의 경험을 연결하여 설명하는 것이 좋다.'),
('n1-0073','2026-10-10','多様','たよう','다양함; 여러 가지임','種類や性質などがさまざまで、一つに限られないこと。','多様な働き方を認める制度が整い、社員が勤務時間を選びやすくなった。','다양한 근무 방식을 인정하는 제도가 마련되어 직원들이 근무 시간을 선택하기 쉬워졌다。'),
('n1-0288','2026-10-10','再建','さいけん','재건; 재정비; 회복','壊れたり衰えたりした建物・組織・経営・制度などを、再び成り立つ状態に立て直すこと。','経営が悪化した会社を再建するため、事業の選択と集中が進められた。','경영이 악화된 회사를 재건하기 위해 사업의 선택과 집중이 추진되었다.'),
('n1-0289','2026-10-10','進出','しんしゅつ','진출','新しい地域・市場・分野などへ活動範囲や勢力を広げて出ていくこと。','国内市場が成熟したため、多くの企業が東南アジアへの進出を検討している。','국내 시장이 성숙했기 때문에 많은 기업이 동남아시아 진출을 검토하고 있다.'),
('n1-2903','2026-10-10','堪える','たえる','견디다; 참다; 감당하다','苦痛・困難などを我慢して持ちこたえる。また、ある役目に耐え得る。','厳しい寒さに堪えて作業を続けた。','혹독한 추위를 견디며 작업을 계속했다.'),
('n1-0290','2026-10-10','様式','ようしき','양식; 형식; 방식','一定の形式や方法。また、時代・文化・分野などに共通して見られる表現上の特徴。','申請書は指定された様式を使用し、必要事項をすべて記入してください。','신청서는 지정된 양식을 사용하여 필요한 사항을 모두 기입해 주세요.'),
('n1-0292','2026-10-10','放棄','ほうき','포기; 방기; 권리 등을 버림','権利・責任・所有物・計画など、自分が持っていたものや行おうとしていたことを捨てること。','困難が続いても、十分な検討なしに計画そのものを放棄するべきではない。','어려움이 계속되더라도 충분한 검토 없이 계획 자체를 포기해서는 안 된다.'),
('n1-0293','2026-10-10','主催','しゅさい','주최; 주관','行事・大会・会合などを責任を持って企画し、中心となって開催すること。','このセミナーは市が主催し、地元企業の経営者を対象に無料で開かれる。','이 세미나는 시가 주최하며 지역 기업 경영자를 대상으로 무료로 열린다.'),
('n1-0294','2026-10-10','移民','いみん','이민; 이민자','生活・労働などのために自国を離れて他国へ移り住むこと。また、その人。','労働力不足を背景に、移民の受け入れ政策を見直す国が増えている。','노동력 부족을 배경으로 이민 수용 정책을 재검토하는 나라가 늘고 있다.'),
('n1-0295','2026-10-10','阻止','そし','저지; 막음','ある行動・計画・進行などを途中で止め、実現しないようにすること。','不正アクセスを阻止するため、異常な通信を自動で遮断する仕組みを導入した。','부정 접근을 저지하기 위해 비정상 통신을 자동 차단하는 구조를 도입했다.'),
('n1-0296','2026-10-10','抑制','よくせい','억제; 제어','感情・欲望・増加・活動などが強くなりすぎないよう抑えること。','物価上昇を抑制するため、政府は複数の経済対策を実施した。','물가 상승을 억제하기 위해 정부는 여러 경제 대책을 실시했다.'),
('n1-0297','2026-10-10','本質','ほんしつ','본질; 본성','表面的な特徴ではなく、ある物事をそのものとして成り立たせている根本的な性質。','数字だけを追っていると、利用者が困っている問題の本質を見失うことがある。','숫자만 쫓다 보면 이용자가 곤란해하는 문제의 본질을 놓칠 수 있다.'),
('n1-0298','2026-10-10','確定','かくてい','확정; 확정됨','内容・結果・予定などを最終的にはっきり決め、変更しない状態にすること。','参加者の人数が確定したら、会場と座席配置を最終調整する。','참가자 수가 확정되면 행사장과 좌석 배치를 최종 조정한다.'),
('n1-0299','2026-10-10','侵略','しんりゃく','침략','他国の領土・主権などを奪う目的で、武力などを用いて攻め入ること。','他国への侵略を正当化するために歴史を歪めてはならない。','다른 나라에 대한 침략을 정당화하기 위해 역사를 왜곡해서는 안 된다.');
INSERT INTO _n1_b1_words_0099(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0303','2026-10-11','紛争','ふんそう','분쟁; 갈등','国・地域・組織・集団などの間で、利害や主張をめぐって激しく争うこと。','長引く地域紛争によって、多くの住民が住む場所を失っている。','장기화되는 지역 분쟁으로 많은 주민이 살 곳을 잃고 있다.'),
('n1-0305','2026-10-11','統制','とうせい','통제; 통솔','一定の方針や目的に従わせるため、組織・行動・活動などをまとめて制御すること。','緊急時には指揮系統を明確にし、組織全体の行動を統制する必要がある。','긴급 상황에서는 지휘 체계를 명확히 하여 조직 전체의 행동을 통제할 필요가 있다.'),
('n1-0306','2026-10-11','占領','せんりょう','점령; 점거','軍事力などによって他の国や地域を支配下に置くこと。また、場所を独り占めする意味でも使う。','戦争中、この地域は長期間にわたって外国軍に占領されていた。','전쟁 중 이 지역은 장기간 외국군에 점령되어 있었다.'),
('n1-0307','2026-10-11','機構','きこう','기구; 조직; 작동 구조','組織が働く仕組みや構造。また、一定の目的のために作られた組織・機関。','国際的な監視機構を設け、各国の実施状況を定期的に確認する案が示された。','국제적인 감시 기구를 설치하여 각국의 실시 상황을 정기적으로 확인하는 방안이 제시되었다.'),
('n1-0308','2026-10-11','促進','そくしん','촉진; 증진','物事の進行・発達・成長などがより速く進むよう働きかけること。','地域経済の活性化を促進するため、中小企業への支援策が拡充された。','지역 경제 활성화를 촉진하기 위해 중소기업 지원책이 확대되었다.'),
('n1-0309','2026-10-11','賃金','ちんぎん','임금; 노동의 대가','労働の対価として使用者から労働者に支払われる金銭。','物価の上昇に賃金の伸びが追いつかなければ、実質的な生活水準は下がる。','물가 상승을 임금 상승이 따라가지 못하면 실질적인 생활 수준은 낮아진다.'),
('n1-0316','2026-10-11','情勢','じょうせい','정세; 상황; 형세','社会・政治・経済・国際関係などが変化していく全体的な状況や成り行き。','国際情勢が急速に変化しているため、事業計画を柔軟に見直す必要がある。','국제 정세가 빠르게 변하고 있어 사업 계획을 유연하게 재검토할 필요가 있다.'),
('n1-0319','2026-10-11','事前','じぜん','사전; 미리','ある事柄が起こる前、または何かを行う前。','トラブルを防ぐため、変更内容は利用者に事前に通知してください。','문제를 방지하기 위해 변경 내용은 이용자에게 사전에 알려 주세요.'),
('n1-0333','2026-10-11','手法','しゅほう','수법; 기법; 방법','ある目的を達成したり作品を表現したりするために用いる具体的な方法・技法。','従来とは異なる分析手法を使うことで、見落としていた傾向が明らかになった。','기존과 다른 분석 기법을 사용함으로써 놓치고 있던 경향이 드러났다.'),
('n1-0334','2026-10-11','特権','とっけん','특권; 특별한 권리','特定の地位・身分・集団などにだけ認められる特別な権利や利益。','役職を私的な特権のように扱う姿勢は、組織への信頼を損なう。','직책을 사적인 특권처럼 다루는 태도는 조직에 대한 신뢰를 훼손한다.'),
('n1-0342','2026-10-11','経緯','いきさつ','경위; 자초지종; 일이 진행된 과정','ある出来事が現在の状態に至るまでの事情や過程。『けいい』とも読む。','なぜ計画が中止になったのか、その経緯を関係者に詳しく説明してもらった。','왜 계획이 중지되었는지 그 경위를 관계자에게 자세히 설명받았다.'),
('n1-0344','2026-10-11','介入','かいにゅう','개입; 관여','本来は直接の当事者でない人・組織・国家などが、他者の問題や関係に入り込み影響を与えること。','政府が市場に過度に介入すれば、自由な競争が損なわれるという意見もある。','정부가 시장에 지나치게 개입하면 자유로운 경쟁이 훼손된다는 의견도 있다.'),
('n1-0345','2026-10-11','提示','ていじ','제시; 보여 줌','条件・資料・証明書・考えなどを相手に示して見せること。','受付では本人確認のため、身分証明書の提示を求められる。','접수처에서는 본인 확인을 위해 신분증 제시를 요구받는다.'),
('n1-0348','2026-10-11','進展','しんてん','진전; 발전','物事や交渉・研究などが前の段階から進み、新しい展開を見せること。','交渉は長く停滞していたが、双方が譲歩したことで大きな進展があった。','협상은 오랫동안 정체되어 있었지만 양측이 양보하면서 큰 진전이 있었다.'),
('n1-0356','2026-10-11','緩和','かんわ','완화; 누그러뜨림','厳しさ・緊張・痛み・規制・条件などの程度を弱め、穏やかにすること。','人手不足を緩和するため、業務の自動化と採用拡大を同時に進めている。','인력 부족을 완화하기 위해 업무 자동화와 채용 확대를 동시에 추진하고 있다.'),
('n1-0371','2026-10-11','個性','こせい','개성; 고유한 특성','他の人や物とは異なる、その人・その物に固有の性質や特徴。','全員を同じ型にはめるより、それぞれの個性を生かせる環境を作るほうがよい。','모두를 같은 틀에 맞추기보다 각자의 개성을 살릴 수 있는 환경을 만드는 편이 좋다.'),
('n1-0385','2026-10-11','制定','せいてい','제정','法律・規則・制度などを正式に作り、定めること。','個人情報を適切に扱うため、社内で新しい管理規程を制定した。','개인정보를 적절히 다루기 위해 사내에 새로운 관리 규정을 제정했다.'),
('n1-0389','2026-10-11','応募','おうぼ','응모; 지원','求人・作品募集・企画などの募集に応じて申し込むこと。','海外勤務の社内公募に応募するには、一定の語学力が必要だ。','해외 근무 사내 공모에 지원하려면 일정한 어학 능력이 필요하다.'),
('n1-0399','2026-10-11','妥協','だきょう','타협; 절충','対立する双方が、それぞれ一部を譲って一致できる点を見つけること。','双方が少しずつ条件を譲り、ようやく妥協案に合意した。','양측이 조금씩 조건을 양보하여 마침내 타협안에 합의했다.'),
('n1-0406','2026-10-11','実態','じったい','실태; 실제 상태','表面的な説明や建前ではなく、実際に存在している状態やありさま。','長時間労働の実態を把握するため、会社は全社員の勤務記録を調査した。','장시간 노동의 실태를 파악하기 위해 회사는 전 직원의 근무 기록을 조사했다.'),
('n1-0427','2026-10-12','領土','りょうど','영토','国家が主権を行使し、領有している土地の範囲。','領土をめぐる対立が長期化し、両国の外交関係にも影響が出ている。','영토를 둘러싼 대립이 장기화되어 양국의 외교 관계에도 영향이 나타나고 있다.'),
('n1-0442','2026-10-12','途上','とじょう','도중; 과정 중; 발전 단계','目的地や完成・発展へ向かっている途中。『発展途上』『帰宅の途上』などの形で使う。','この技術はまだ発展途上であり、実用化までには多くの課題が残っている。','이 기술은 아직 발전 도중에 있어 실용화까지 많은 과제가 남아 있다.'),
('n1-0454','2026-10-12','個別','こべつ','개별; 각각 따로','全体を一括して扱わず、一つ一つを別々に扱うこと。','全体説明の後、希望者には個別の相談時間を設ける予定だ。','전체 설명 후 희망자에게는 개별 상담 시간을 마련할 예정이다.'),
('n1-0463','2026-10-12','理性','りせい','이성; 합리적으로 판단하는 능력','感情や欲望だけに左右されず、筋道を立てて考え判断する能力。','強い怒りを感じても、理性を失わず事実を確認してから行動することが大切だ。','강한 분노를 느끼더라도 이성을 잃지 않고 사실을 확인한 뒤 행동하는 것이 중요하다.'),
('n1-0487','2026-10-12','討論','とうろん','토론; 논쟁','ある問題について複数の人が意見を出し、賛否や論点を整理しながら議論すること。','授業では賛成派と反対派に分かれ、エネルギー政策について討論した。','수업에서는 찬성파와 반대파로 나뉘어 에너지 정책에 대해 토론했다.'),
('n1-0517','2026-10-12','異論','いろん','이론; 다른 의견; 이견','ある意見・判断に対して示される、異なる意見や反対の見解。','方針そのものには異論はないが、実施時期については再検討が必要だと思う。','방침 자체에는 이견이 없지만 실시 시기에 대해서는 재검토가 필요하다고 생각한다.'),
('n1-0518','2026-10-12','構想','こうそう','구상; 큰 틀의 계획','これから実現しようとする物事について、全体の内容・規模・方法などを組み立てて考えること。また、その考え。','新しい都市開発の構想には、住宅だけでなく教育施設や公園も含まれている。','새 도시 개발 구상에는 주택뿐 아니라 교육시설과 공원도 포함되어 있다.'),
('n1-0529','2026-10-12','立法','りっぽう','입법; 법률 제정','国会などの立法機関が法律を制定すること。','技術の進歩が速いため、立法が社会の変化に追いついていないという指摘がある。','기술 발전이 빨라 입법이 사회 변화에 따라가지 못한다는 지적이 있다.'),
('n1-0543','2026-10-12','客観','きゃっかん','객관; 객관적인 관점','個人的な感情や思い込みを離れ、事実をありのままに捉えようとする立場・見方。','自分の案だけにこだわらず、客観的なデータをもとに判断する必要がある。','자기 안만 고집하지 말고 객관적인 데이터를 바탕으로 판단할 필요가 있다.'),
('n1-0544','2026-10-12','提携','ていけい','제휴; 협력 관계를 맺음','共通の目的や利益のために、企業・団体などが協力関係を結ぶこと。','両社は海外市場の開拓を目的に業務提携を結んだ。','양사는 해외 시장 개척을 목적으로 업무 제휴를 맺었다.'),
('n1-0646','2026-10-12','主権','しゅけん','주권','国家の政治や方針を最終的に決定する最高の権力。','主権を尊重しながら国際協力を進めることが外交の基本原則とされる。','주권을 존중하면서 국제 협력을 추진하는 것이 외교의 기본 원칙으로 여겨진다.'),
('n1-0652','2026-10-12','外観','がいかん','외관; 겉모습','建物・物体などを外から見たときの形や様子。','歴史的な外観を残しながら、建物内部だけを現代的に改修した。','역사적인 외관은 남기면서 건물 내부만 현대적으로 개수했다.'),
('n1-0653','2026-10-12','知性','ちせい','지성; 이해·판단 능력','物事を理解し、考え、判断する知的な能力。','豊富な知識だけでなく、それを適切に使う知性も専門家には求められる。','풍부한 지식뿐 아니라 그것을 적절히 활용하는 지성도 전문가에게 요구된다.'),
('n1-0655','2026-10-12','正規','せいき','정규; 정식','正式な規則・手続き・基準に従っていること。','正規の手続きを経ずに設定を変更すると、監査で問題になる可能性がある。','정규 절차를 거치지 않고 설정을 변경하면 감사에서 문제가 될 수 있다.'),
('n1-0661','2026-10-12','楽観','らっかん','낙관; 긍정적으로 전망함','物事の成り行きを明るく、うまくいくものとして考えること。','売上が一時的に伸びたからといって、今後の市場を楽観しすぎるのは危険だ。','매출이 일시적으로 늘었다고 해서 앞으로의 시장을 지나치게 낙관하는 것은 위험하다.'),
('n1-0665','2026-10-12','規約','きやく','규약; 운영 규칙','組織・サービスなどの構成員や利用者が守るべき規則をまとめたもの。','サービスを利用する前に、個人情報の扱いを定めた規約を確認してください。','서비스를 이용하기 전에 개인정보 취급을 정한 규약을 확인해 주세요.'),
('n1-0675','2026-10-12','悲観','ひかん','비관; 부정적으로 전망함','物事の成り行きを悪い方向へ進むものとして考えること。','短期的な数字だけを見て将来を悲観する必要はない。','단기적인 수치만 보고 미래를 비관할 필요는 없다.'),
('n1-0679','2026-10-12','制約','せいやく','제약; 제한 조건','行動・設計・選択などの範囲を狭める条件や制限。','予算と納期の制約があるため、すべての機能を同時に実装することはできない。','예산과 납기의 제약이 있어 모든 기능을 동시에 구현할 수는 없다.'),
('n1-0688','2026-10-12','規範','きはん','규범; 행동 기준','社会・集団の中で行動や判断の基準として守るべき原則。','技術者には法律だけでなく、職業上の倫理規範を守る責任もある。','기술자는 법률뿐 아니라 직업상의 윤리 규범을 지킬 책임도 있다.'),
('n1-0736','2026-10-12','言論','げんろん','언론; 말과 글을 통한 의견 표현','考え・意見・主張を、言葉や文章によって公に表すこと。','民主社会では言論の自由が重要な権利として保障されている。','민주사회에서는 언론의 자유가 중요한 권리로 보장되어 있다.');
INSERT INTO _n1_b1_words_0099(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0737','2026-10-13','論議','ろんぎ','논의; 논쟁','ある問題について、複数の人が意見を述べ合い議論すること。','制度の見直しをめぐって、専門家の間で活発な論議が続いている。','제도 재검토를 둘러싸고 전문가들 사이에서 활발한 논의가 계속되고 있다.'),
('n1-0744','2026-10-13','主観','しゅかん','주관; 주관적 관점','自分自身の立場・感情・考えを基準として物事を見ること。','評価には主観が入りやすいため、複数の指標を使う必要がある。','평가에는 주관이 개입하기 쉬워 여러 지표를 사용할 필요가 있다.'),
('n1-0774','2026-10-13','制裁','せいさい','제재; 처벌 조치','規則違反・不正行為などに対して加えられる処罰・不利益な措置。','国際社会は合意に違反した国に対して経済制裁を強化した。','국제사회는 합의를 위반한 국가에 경제 제재를 강화했다.'),
('n1-0794','2026-10-13','方策','ほうさく','방책; 해결 방안','問題を解決したり目的を達成したりするための方法・手段。','人口減少への有効な方策を自治体と住民が共同で検討している。','인구 감소에 대한 효과적인 방책을 지자체와 주민이 함께 검토하고 있다.'),
('n1-0884','2026-10-13','概略','がいりゃく','개략; 대략적인 내용','物事の主要な部分だけを簡単にまとめた内容。','まず計画の概略を説明し、その後で各工程の詳細に入ります。','먼저 계획의 개략을 설명한 뒤 각 공정의 상세 내용으로 들어가겠습니다.'),
('n1-0908','2026-10-13','弁論','べんろん','변론; 논리적으로 주장함','自分の立場・意見を論理的に述べること。特に法廷で当事者・弁護人が主張を述べること。','裁判では双方の弁論を聞いたうえで、裁判官が判断を示す。','재판에서는 양측의 변론을 들은 뒤 판사가 판단을 내린다.'),
('n1-0988','2026-10-13','証拠','しょうこ','증거; 증거물','事実・主張が正しいことを示す根拠・材料。','判断を下す前に、客観的な証拠が十分にあるか確認する必要がある。','판단을 내리기 전에 객관적인 증거가 충분한지 확인할 필요가 있다.'),
('n1-1019','2026-10-13','拒否','きょひ','거부','要求・提案・受け取りなどを受け入れないこと。','本人には、個人情報の提供を拒否する権利がある。','본인에게는 개인정보 제공을 거부할 권리가 있다.'),
('n1-1027','2026-10-13','把握','はあく','파악; 정확히 이해함','内容・状況・全体像などをしっかり理解すること。','障害の影響範囲を正確に把握してから復旧作業を始める。','장애의 영향 범위를 정확히 파악한 뒤 복구 작업을 시작한다.'),
('n1-1054','2026-10-13','世論','せろん','여론','社会の多くの人々が共有する意見・評価。『よろん』とも読む。','政策への世論の反応を受け、政府は説明会を追加で開くことにした。','정책에 대한 여론의 반응을 받아 정부는 설명회를 추가로 열기로 했다.'),
('n1-1059','2026-10-13','効率','こうりつ','효율; 능률','投入した時間・労力・費用に対して、どれだけ成果を得られるかという割合・程度。','作業手順を標準化したことで、処理効率が大幅に向上した。','작업 절차를 표준화해 처리 효율이 크게 향상됐다.'),
('n1-1063','2026-10-13','秩序','ちつじょ','질서','社会・集団・物事が混乱せず、一定の規則・順序に従って保たれている状態。','多くの人が利用する場所では、秩序を保つための明確なルールが必要だ。','많은 사람이 이용하는 장소에서는 질서를 유지하기 위한 명확한 규칙이 필요하다.'),
('n1-1114','2026-10-13','破損','はそん','파손; 망가짐','物が壊れたり傷んだりして、本来の状態・機能を失うこと。','輸送中に商品が破損した場合は交換の対象となる。','운송 중 상품이 파손된 경우 교환 대상이 된다.'),
('n1-1162','2026-10-13','規格','きかく','규격; 표준','製品・材料・方法などについて定められた寸法・品質・形式などの標準。','部品が国際規格に適合しているか確認する必要がある。','부품이 국제 규격에 적합한지 확인할 필요가 있다.'),
('n1-1170','2026-10-13','拒絶','きょぜつ','거절; 거부','要求・提案・接触などを強く退け、受け入れないこと。','相手の提案を全面的に拒絶する前に、条件を整理して話し合うべきだ。','상대의 제안을 전면 거절하기 전에 조건을 정리해 논의해야 한다.'),
('n1-1207','2026-10-13','用件','ようけん','용건; 볼일','人に会う・連絡するなどの目的となる事柄。','電話の用件を簡潔に伝えてから担当者につないでもらった。','전화 용건을 간단히 전달한 뒤 담당자에게 연결받았다.'),
('n1-1248','2026-10-13','損失','そんしつ','손실','財産・利益・価値・機会などを失って生じる損害。','障害によるサービス停止で大きな損失が発生した。','장애로 인한 서비스 중단으로 큰 손실이 발생했다.'),
('n1-1258','2026-10-13','履歴','りれき','이력; 경력 기록','これまでに経験した学業・職業・活動などの経歴。また、処理・操作などの記録。','操作履歴を確認すると、設定変更の時刻が特定できた。','작업 이력을 확인하니 설정 변경 시각을 특정할 수 있었다.'),
('n1-1271','2026-10-13','妨害','ぼうがい','방해; 저지','物事が順調に進まないよう邪魔をしたり、活動を阻んだりすること。','通信を意図的に妨害する行為は禁止されている。','통신을 의도적으로 방해하는 행위는 금지되어 있다.'),
('n1-1272','2026-10-13','製法','せいほう','제조법; 만드는 방법','製品・食品・材料などを作る方法。','伝統的な製法を守りながら、生産工程の一部を自動化した。','전통적인 제조법을 지키면서 생산 공정 일부를 자동화했다.'),
('n1-1286','2026-10-14','法廷','ほうてい','법정','裁判官・当事者などが集まり、裁判の審理を行う場所。','証人は法廷で当時の状況を詳しく説明した。','증인은 법정에서 당시 상황을 자세히 설명했다.'),
('n1-1416','2026-10-14','脅迫','きょうはく','협박; 위협','相手を怖がらせる言葉・行動によって、何かを強制したり害を加えると告げたりすること。','金を払わなければ情報を公開すると脅迫するメールが届いた。','돈을 내지 않으면 정보를 공개하겠다고 협박하는 메일이 도착했다.'),
('n1-1444','2026-10-14','公募','こうぼ','공모; 공개 모집','資格・作品・人材などを、広く一般に知らせて募集すること。','市は新しいロゴのデザインを一般から公募している。','시는 새로운 로고 디자인을 일반에 공모하고 있다.'),
('n1-1473','2026-10-14','荒廃','こうはい','황폐; 피폐','土地・建物・社会・生活などが荒れ、機能や活力を失った状態になること。','人口流出が続き、中心街の荒廃が深刻な問題になっている。','인구 유출이 계속돼 중심가의 황폐화가 심각한 문제가 되고 있다.'),
('n1-1514','2026-10-14','紛失','ふんしつ','분실','持っていた物を、どこに置いたか分からなくなり失うこと。','社員証を紛失した場合は、すぐに管理部へ連絡してください。','사원증을 분실한 경우 즉시 관리부에 연락해 주세요.'),
('n1-1517','2026-10-14','停滞','ていたい','정체; 침체','物事の進展・成長が止まり、同じ状態が続くこと。','需要の低迷により、国内市場の成長は停滞している。','수요 침체로 국내 시장의 성장은 정체되어 있다.'),
('n1-1526','2026-10-14','覆面','ふくめん','복면; 신원을 숨김','顔を布などで覆って素顔を隠すこと。また、正体を明かさず活動すること。','覆面の男が店に押し入り、警察が行方を追っている。','복면을 쓴 남자가 가게에 침입해 경찰이 행방을 쫓고 있다.'),
('n1-1551','2026-10-14','態勢','たいせい','태세; 준비 체제','ある事態・行動に対応するために整えた人員・組織・準備の状態。','連休中の問い合わせ増加に備え、サポート態勢を強化した。','연휴 중 문의 증가에 대비해 지원 태세를 강화했다.'),
('n1-1598','2026-10-14','抑圧','よくあつ','억압','権力・圧力によって人の自由な行動・感情・意見などを強く押さえつけること。','表現の自由を抑圧する制度には強い批判が集まった。','표현의 자유를 억압하는 제도에 강한 비판이 모였다.'),
('n1-1620','2026-10-14','過疎','かそ','과소화; 인구 과소','人口が大きく減り、地域社会の維持に必要な人数が不足している状態。','山間部では過疎と高齢化が同時に進んでいる。','산간 지역에서는 인구 과소화와 고령화가 동시에 진행되고 있다.'),
('n1-1660','2026-10-14','適性','てきせい','적성; 적합한 성질·능력','特定の仕事・活動などに向いている性質・能力。','配属前に本人の希望だけでなく職務への適性も確認する。','배치 전에 본인 희망뿐 아니라 직무 적성도 확인한다.'),
('n1-1682','2026-10-14','棄権','きけん','기권','選挙・投票・競技などに参加する権利を自ら行使しないこと。','けがが悪化し、選手は決勝戦を棄権した。','부상이 악화되어 선수는 결승전을 기권했다.'),
('n1-1695','2026-10-14','良識','りょうしき','양식; 건전한 판단력','社会常識・道理に照らして物事を適切に判断する健全な能力。','利用者一人ひとりの良識ある行動が求められている。','이용자 한 사람 한 사람의 양식 있는 행동이 요구된다.'),
('n1-1712','2026-10-14','譲歩','じょうほ','양보; 타협을 위해 물러섬','交渉などで自分の主張・条件の一部を引き、相手側を受け入れること。','双方が少しずつ譲歩したことで、ようやく合意に達した。','양측이 조금씩 양보해 마침내 합의에 도달했다.'),
('n1-1773','2026-10-14','法案','ほうあん','법안','法律として成立させるために、国会などの立法機関へ提出される案。','政府は来週、制度改正に関する法案を国会に提出する予定だ。','정부는 다음 주 제도 개정에 관한 법안을 국회에 제출할 예정이다.'),
('n1-1904','2026-10-14','徴収','ちょうしゅう','징수; 거두어들임','税金・料金などを、決められた基準に従って取り立てて集めること。','利用料金は毎月の給与から一括して徴収される。','이용 요금은 매달 급여에서 일괄 징수된다.'),
('n1-2188','2026-10-14','滞納','たいのう','체납; 연체','税金・料金などを期限までに納めず、支払いが遅れていること。','税金を滞納すると延滞金が発生することがある。','세금을 체납하면 연체금이 발생할 수 있다.'),
('n1-2217','2026-10-14','欠乏','けつぼう','결핍; 부족','必要なものが不足していること。','深刻な水不足で飲料水が欠乏している。','심각한 물 부족으로 식수가 결핍되어 있다.'),
('n1-2269','2026-10-14','窮乏','きゅうぼう','궁핍; 빈곤','生活に必要な物資・金銭などが不足し、非常に苦しい状態にあること。','戦後、多くの人々が深刻な窮乏生活を送った。','전후 많은 사람들이 심각한 궁핍 생활을 했다.'),
('n1-2713','2026-10-14','妥結','だけつ','타결; 합의 성립','対立する双方が譲歩し、話し合いをまとめること。','長い交渉の末、労使交渉が妥結した。','긴 협상 끝에 노사 협상이 타결됐다.');
INSERT INTO japanese_words(word,reading,meaning_ko,meaning_ja,jlpt_level_id,ai_status,note) SELECT s.word,s.reading,s.meaning_ko,s.meaning_ja,(SELECT id FROM jlpt_levels WHERE code='N1'),'reviewed','JLPT N1 batch 2026-10-01..2026-10-14' FROM _n1_b1_words_0099 s WHERE NOT EXISTS (SELECT 1 FROM japanese_words w WHERE w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL);
INSERT INTO _n1_b1_map_0099(source_key,word_id) SELECT s.source_key,MIN(w.id) FROM _n1_b1_words_0099 s JOIN japanese_words w ON w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL GROUP BY s.source_key;
