INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0083","prompt":"「設立」の読み方として最も適切なものを選びなさい。","options":["そうごう","けいかい","どくせん","せつりつ"],"answer":"せつりつ","explanationKo":"「設立」는 「せつりつ」라고 읽는다. 뜻은 설립이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0984","prompt":"「及ぶ」の読み方として最も適切なものを選びなさい。","options":["かく","ごまかす","およぶ","たえる"],"answer":"およぶ","explanationKo":"「及ぶ」는 「およぶ」라고 읽는다. 뜻은 미치다; 이르다; 필적하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0081","prompt":"「名誉」の読み方として最も適切なものを選びなさい。","options":["ふとう","めいよ","きょくたん","どうてき"],"answer":"めいよ","explanationKo":"「名誉」는 「めいよ」라고 읽는다. 뜻은 명예; 영예이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0084","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n十分な説明をしないまま計画を変更したとして、会社は利用者から（　）を受けた。","options":["非難","世代","根本","動機"],"answer":"非難","explanationKo":"문맥상 「非難」가 가장 자연스럽다. 비난라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0086","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n報告書には、実験の手順と結果を客観的に（　）する必要がある。","options":["観点","個別","秩序","記述"],"answer":"記述","explanationKo":"문맥상 「記述」가 가장 자연스럽다. 기술; 서술라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1037","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n会社全体で業務のデジタル化に（　）必要がある。","options":["覆す","制する","取り組む","紛れる"],"answer":"取り組む","explanationKo":"문맥상 「取り組む」가 가장 자연스럽다. 몰두하다; 적극적으로 임하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0089","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n自治体は大雪に備え、不要不急の外出を控えるよう住民に（　）した。","options":["確信","要請","象徴","対抗"],"answer":"要請","explanationKo":"문맥상 「要請」가 가장 자연스럽다. 요청; 요구라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0108","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの会社は（　）の技術を生かし、海外市場でも高い評価を得ている。","options":["独自","敢えて","知的","緩やか"],"answer":"独自","explanationKo":"문맥상 「独自」가 가장 자연스럽다. 독자적; 고유함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0091","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n工事の（　）が予定より遅れているため、工程を見直すことになった。","options":["抑制","提携","抑圧","進行"],"answer":"進行","explanationKo":"문맥상 「進行」가 가장 자연스럽다. 진행; 진척라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0095","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n保存期限を過ぎた書類は、規定に従って適切に（　）しなければならない。","options":["連邦","実質","処分","荒廃"],"answer":"処分","explanationKo":"문맥상 「処分」가 가장 자연스럽다. 처분; 처리; 징계 처분라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1071","prompt":"「建物・土台などを作る。また比喩的に、信頼・地位・関係などを長い時間をかけて作り上げる。」という意味に最も近い語を選びなさい。","options":["準ずる","築く","堪える","逸らす"],"answer":"築く","explanationKo":"「築く」의 핵심 의미는 쌓다; 구축하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0111","prompt":"「すべてのこと。多く否定表現とともに用いて、『まったく何も』の意を表す。」という意味に最も近い語を選びなさい。","options":["一切","従来","厳密","多様"],"answer":"一切","explanationKo":"「一切」의 핵심 의미는 일절; 일체; 전부이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0100","prompt":"「ある形・状態・関係などを作り上げること。また、次第に作られること。」という意味に最も近い語を選びなさい。","options":["法案","任命","回収","形成"],"answer":"形成","explanationKo":"「形成」의 핵심 의미는 형성; 만들어짐이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0103","prompt":"「国家間などで、権利や義務について正式に取り決めた国際的な合意。」という意味に最も近い語を選びなさい。","options":["経緯","証拠","条約","職務"],"answer":"条約","explanationKo":"「条約」의 핵심 의미는 조약이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1074","prompt":"「責任・義務・負傷・損害などを引き受ける。また、背中に物を載せる。」という意味に最も近い語を選びなさい。","options":["犯す","負う","募る","掲げる"],"answer":"負う","explanationKo":"「負う」의 핵심 의미는 지다; 책임지다; 입다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','grammar',1,'〜あっての','{"pattern":"〜あっての","meaningKo":"〜이 있어야 비로소","explanation":"〜あっての는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"支えてくれる地域の人々あっての祭りなので、主催者だけの判断では変えられない。","ko":"문맥에서 〜이 있어야 비로소의 의미로 쓰였다."},{"ja":"顧客あっての商売だという基本を忘れてはならない。","ko":"이 문장도 〜이 있어야 비로소의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','grammar',2,'〜いかんでは','{"pattern":"〜いかんでは","meaningKo":"〜여하에 따라서는","explanation":"〜いかんでは는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今後の交渉の進み方いかんでは、計画を根本から見直す必要もある。","ko":"문맥에서 〜여하에 따라서는의 의미로 쓰였다."},{"ja":"検査の結果いかんでは、追加の調査を行うことになる。","ko":"이 문장도 〜여하에 따라서는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n支えてくれる地域の人々（　）祭りなので、主催者だけの判断では変えられない。","options":["〜あっての","〜そばから","〜てやまない","〜に足る"],"answer":"〜あっての","explanationKo":"문맥상 〜이 있어야 비로소를 나타내는 「〜あっての」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今後の交渉の進み方（　）、計画を根本から見直す必要もある。","options":["〜たところで","〜とあって","〜にもまして","〜いかんでは"],"answer":"〜いかんでは","explanationKo":"문맥상 〜여하에 따라서는를 나타내는 「〜いかんでは」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n経験の有無（　）、応募者には同じ課題が課される。","options":["〜とあれば","〜ばこそ","〜いかんにかかわらず","〜だに"],"answer":"〜いかんにかかわらず","explanationKo":"문맥상 〜여하에 관계없이를 나타내는 「〜いかんにかかわらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-01','reading',1,'効率化が生む余白','{"passage":"仕事の効率化は、同じ成果をより短い時間で得るために行われる。しかし、空いた時間にさらに多くの仕事を詰め込むだけなら、働く人の負担は軽くならない。効率化によって生まれた余白を、検討や対話、技能の習得に使ってこそ、長期的な改善につながる。速さを測るだけでは、判断の質や新しい発想の価値は見えにくい。重要なのは、時間を削ること自体ではなく、削って得た時間を何に振り向けるかをあらかじめ決めておくことである。","questions":[{"prompt":"筆者が効率化について最も重視していることは何か。","options":["生まれた時間の使い道を決めること","すべての作業を機械に任せること","短時間で処理した件数だけを評価すること","空いた時間に仕事を追加すること"],"answer":"生まれた時間の使い道を決めること","explanationKo":"효율화로 생긴 시간을 무엇에 쓸지 정하는 것이 중요하다고 본다."},{"prompt":"本文によれば、速さだけでは捉えにくいものは何か。","options":["判断の質や新しい発想の価値","作業に必要な人数","勤務時間の長さ","処理した仕事の件数"],"answer":"判断の質や新しい発想の価値","explanationKo":"속도만으로는 판단의 질과 새로운 발상의 가치를 보기 어렵다."},{"prompt":"本文の内容と合うものはどれか。","options":["効率化の成果は余白の活用方法にも左右される","効率化すれば必ず仕事量を増やすべきだ","対話の時間は効率化の妨げになる","長期的改善には速さだけが必要だ"],"answer":"効率化の成果は余白の活用方法にも左右される","explanationKo":"효율화의 성과는 확보한 여유 시간을 어떻게 활용하는지에도 달려 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0121","prompt":"「対処」の読み方として最も適切なものを選びなさい。","options":["たいしょ","どうにゅう","そうごう","けいかい"],"answer":"たいしょ","explanationKo":"「対処」는 「たいしょ」라고 읽는다. 뜻은 대처; 대응이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1079","prompt":"「仕える」の読み方として最も適切なものを選びなさい。","options":["ひきいる","たずさわる","たえる","つかえる"],"answer":"つかえる","explanationKo":"「仕える」는 「つかえる」라고 읽는다. 뜻은 섬기다; 모시다; 상관 아래에서 일하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0167","prompt":"「有力」の読み方として最も適切なものを選びなさい。","options":["もろい","きょくたん","ゆうりょく","ゆうかん"],"answer":"ゆうりょく","explanationKo":"「有力」는 「ゆうりょく」라고 읽는다. 뜻은 유력; 영향력이 큼; 가능성이 높음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0126","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n申請前に注意（　）をよく読み、必要な書類がそろっているか確認してください。","options":["決意","事項","同盟","反乱"],"answer":"事項","explanationKo":"문맥상 「事項」가 가장 자연스럽다. 사항; 항목라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0130","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n専門用語を理解するには、まずその背景にある基本（　）を押さえる必要がある。","options":["概念","合意","主催","個別"],"answer":"概念","explanationKo":"문맥상 「概念」가 가장 자연스럽다. 개념라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1081","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n客観的な根拠を（　）主張は、説得力を持ちにくい。","options":["脅す","緩める","促す","欠く"],"answer":"欠く","explanationKo":"문맥상 「欠く」가 가장 자연스럽다. 결여하다; 빠뜨리다; 부족하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0133","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその事件をきっかけに、要人（　）を防ぐための警備体制が強化された。","options":["象徴","対抗","暗殺","良識"],"answer":"暗殺","explanationKo":"문맥상 「暗殺」가 가장 자연스럽다. 암살라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0170","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n契約を解除するには、相手が納得できる（　）な理由を示す必要がある。","options":["先天的","正当","独自","単独"],"answer":"正当","explanationKo":"문맥상 「正当」가 가장 자연스럽다. 정당함; 타당함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0134","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）によって情報の集め方が異なるため、広報手段も一つに絞れない。","options":["世代","言論","適性","合併"],"answer":"世代","explanationKo":"문맥상 「世代」가 가장 자연스럽다. 세대라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0136","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n個人情報を一般の業務データから（　）して管理する仕組みに変更した。","options":["討論","荒廃","連邦","分離"],"answer":"分離","explanationKo":"문맥상 「分離」가 가장 자연스럽다. 분리라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1086","prompt":"「意見・主義などを強く主張する。また、決まった文句・祈りなどを声に出して言う。」という意味に最も近い語を選びなさい。","options":["慕う","取り組む","唱える","滅ぼす"],"answer":"唱える","explanationKo":"「唱える」의 핵심 의미는 주장하다; 외치다; 읊다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0244","prompt":"「知識・知性・思考に関係するさま。また、知性を感じさせるさま。」という意味に最も近い語を選びなさい。","options":["脆い","知的","多様","勇敢"],"answer":"知的","explanationKo":"「知的」의 핵심 의미는 지적; 지성적인이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0137","prompt":"「言葉や概念が何を意味するか、その範囲や内容を明確に定めること。また、その内容。」という意味に最も近い語を選びなさい。","options":["定義","方策","法案","任命"],"answer":"定義","explanationKo":"「定義」의 핵심 의미는 정의; 정의하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0138","prompt":"「制度・方法・理論・立場などを、確かなものとしてしっかり成立させること。」という意味に最も近い語を選びなさい。","options":["合併","悪化","決断","確立"],"answer":"確立","explanationKo":"「確立」의 핵심 의미는 확립; 정립이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1099","prompt":"「苦痛・圧力・厳しい条件などに負けず、持ちこたえる。」という意味に最も近い語を選びなさい。","options":["顧みる","脅かす","耐える","覆す"],"answer":"耐える","explanationKo":"「耐える」의 핵심 의미는 견디다; 버티다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','grammar',1,'〜いかんにかかわらず','{"pattern":"〜いかんにかかわらず","meaningKo":"〜여하에 관계없이","explanation":"〜いかんにかかわらず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"理由のいかんにかかわらず、許可なく資料を持ち出してはならない。","ko":"문맥에서 〜여하에 관계없이의 의미로 쓰였다."},{"ja":"経験の有無いかんにかかわらず、応募者には同じ課題が課される。","ko":"이 문장도 〜여하에 관계없이의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','grammar',2,'〜ずにはおかない','{"pattern":"〜ずにはおかない","meaningKo":"반드시 〜하게 만들다","explanation":"〜ずにはおかない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"彼の真摯な訴えは、聞く者の心を動かさずにはおかない。","ko":"문맥에서 반드시 〜하게 만들다의 의미로 쓰였다."},{"ja":"この作品は、社会の在り方を考えさせずにはおかない。","ko":"이 문장도 반드시 〜하게 만들다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n理由の（　）、許可なく資料を持ち出してはならない。","options":["〜だに","〜とあれば","〜ばこそ","〜いかんにかかわらず"],"answer":"〜いかんにかかわらず","explanationKo":"문맥상 〜여하에 관계없이를 나타내는 「〜いかんにかかわらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼の真摯な訴えは、聞く者の心を動かさ（　）。","options":["〜といえども","〜べからず","〜ずにはおかない","〜たりとも"],"answer":"〜ずにはおかない","explanationKo":"문맥상 반드시 〜하게 만들다를 나타내는 「〜ずにはおかない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n規則に違反したからには、何らかの処分を受け（　）。","options":["〜までもない","〜ずにはすまない","〜であれ","〜なくして"],"answer":"〜ずにはすまない","explanationKo":"문맥상 〜하지 않고는 끝나지 않다를 나타내는 「〜ずにはすまない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-02','reading',1,'専門家の意見をどう読むか','{"passage":"専門家の説明は重要だが、専門家であるという肩書だけで結論まで正しいと決めるべきではない。専門知識が保証するのは、関連する資料や方法を一般の人より深く理解している可能性であり、価値判断や将来予測まで誤りがないことではない。意見を受け取る側には、何が確認された事実で、どこからが推測なのかを区別する姿勢が求められる。専門家を疑うためではなく、その知識を適切な範囲で活用するための区別である。","questions":[{"prompt":"筆者によれば、専門知識が直接保証しないものは何か。","options":["価値判断や将来予測の正しさ","関連資料への理解","専門分野の方法に関する知識","一般の人より深く検討できる可能性"],"answer":"価値判断や将来予測の正しさ","explanationKo":"전문지식이 가치판단이나 미래예측의 정확성까지 보장하지는 않는다."},{"prompt":"意見を受け取る側に必要な姿勢は何か。","options":["事実と推測を区別すること","すべての説明を拒否すること","肩書のない人の意見だけを聞くこと","将来予測を事実として扱うこと"],"answer":"事実と推測を区別すること","explanationKo":"확인된 사실과 추측을 구분해야 한다."},{"prompt":"この区別の目的として最も適切なものはどれか。","options":["専門知識を適切な範囲で活用するため","専門家の誤りを非難するため","一般人の判断を不要にするため","専門分野を狭くするため"],"answer":"専門知識を適切な範囲で活用するため","explanationKo":"전문지식을 알맞은 범위에서 활용하려는 구분이다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0144","prompt":"「受け入れ」の読み方として最も適切なものを選びなさい。","options":["しさん","うけいれ","けつぼう","ほんのう"],"answer":"うけいれ","explanationKo":"「受け入れ」는 「うけいれ」라고 읽는다. 뜻은 수용; 받아들임이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
