INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1116","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n同じ過ちを二度と（　）ことがないよう、原因を記録して共有した。","options":["犯す","紛れる","覆す","制する"],"answer":"犯す","explanationKo":"문맥상 「犯す」가 가장 자연스럽다. 범하다; 저지르다; 위반하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0150","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n申請書には氏名だけでなく、（　）する部署名も記入してください。","options":["主観","良識","導入","所属"],"answer":"所属","explanationKo":"문맥상 「所属」가 가장 자연스럽다. 소속라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0346","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n会議では立場の違う参加者からも（　）に意見が出され、予定時間を大きく超えた。","options":["有力","疎か","活発","先天的"],"answer":"活発","explanationKo":"문맥상 「活発」가 가장 자연스럽다. 활발; 활기참라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0152","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n環境への負荷を減らすため、工場の排出物に対する（　）が強化された。","options":["抑制","規制","反乱","決意"],"answer":"規制","explanationKo":"문맥상 「規制」가 가장 자연스럽다. 규제라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0153","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n民主主義を維持するには、行政や立法から独立した（　）の役割が重要である。","options":["司法","覆面","分離","入手"],"answer":"司法","explanationKo":"문맥상 「司法」가 가장 자연스럽다. 사법라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1122","prompt":"「人に恩恵を与える。また、処置・加工・装飾・肥料などを加える。」という意味に最も近い語を選びなさい。","options":["堪える","逸らす","準ずる","施す"],"answer":"施す","explanationKo":"「施す」의 핵심 의미는 베풀다; 실시하다; 가하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0350","prompt":"「名前や実績が世間に広く知られていること。」という意味に最も近い語を選びなさい。","options":["極端","著しい","著名","脆い"],"answer":"著名","explanationKo":"「著名」의 핵심 의미는 저명; 유명이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0154","prompt":"「本人の意思にかかわらず、権力や力によって無理に行わせること。」という意味に最も近い語を選びなさい。","options":["法案","強制","経緯","方策"],"answer":"強制","explanationKo":"「強制」의 핵심 의미는 강제이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0155","prompt":"「地位・身分・職務などによって区分された等級。また、社会的・経済的条件の共通する人々の層。」という意味に最も近い語を選びなさい。","options":["階級","滞納","権威","職務"],"answer":"階級","explanationKo":"「階級」의 핵심 의미는 계급; 계층이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1125","prompt":"「目標・任務・発展などを最後まで成し遂げ、結果を得る。」という意味に最も近い語を選びなさい。","options":["紛れる","制する","率いる","遂げる"],"answer":"遂げる","explanationKo":"「遂げる」의 핵심 의미는 이루다; 완수하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','grammar',1,'〜ずにはすまない','{"pattern":"〜ずにはすまない","meaningKo":"〜하지 않고는 끝나지 않다","explanation":"〜ずにはすまない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"こちらの手違いで迷惑をかけた以上、謝罪せずにはすまない。","ko":"문맥에서 〜하지 않고는 끝나지 않다의 의미로 쓰였다."},{"ja":"規則に違反したからには、何らかの処分を受けずにはすまない。","ko":"이 문장도 〜하지 않고는 끝나지 않다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','grammar',2,'〜そばから','{"pattern":"〜そばから","meaningKo":"〜하자마자 곧","explanation":"〜そばから는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"新しい単語を覚えたそばから忘れてしまい、復習の必要性を痛感した。","ko":"문맥에서 〜하자마자 곧의 의미로 쓰였다."},{"ja":"片づけるそばから子どもが玩具を出すので、部屋がなかなか整わない。","ko":"이 문장도 〜하자마자 곧의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこちらの手違いで迷惑をかけた以上、謝罪せ（　）。","options":["〜なくして","〜までもない","〜ずにはすまない","〜であれ"],"answer":"〜ずにはすまない","explanationKo":"문맥상 〜하지 않고는 끝나지 않다를 나타내는 「〜ずにはすまない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n新しい単語を覚えた（　）忘れてしまい、復習の必要性を痛感した。","options":["〜もさることながら","〜そばから","〜てからというもの","〜ならでは"],"answer":"〜そばから","explanationKo":"문맥상 〜하자마자 곧를 나타내는 「〜そばから」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n一人で考え（　）解決しないのだから、専門家に相談した方がよい。","options":["〜たところで","〜てやまない","〜に即して","〜を皮切りに"],"answer":"〜たところで","explanationKo":"문맥상 〜해 보아도를 나타내는 「〜たところで」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-03','reading',1,'記録と記憶','{"passage":"記録を残せば、覚えておく負担は減る。ところが、何でも記録すれば安心だと思うと、後で必要な情報を探す時間が増えてしまう。記録の価値は量ではなく、判断の経緯が再現できるかどうかにある。結論だけでなく、当時の条件、採用しなかった案、その理由を簡潔に残せば、状況が変わった際にも見直しやすい。記録とは記憶の代用品というより、将来の自分や他者が判断を更新するための手掛かりなのである。","questions":[{"prompt":"筆者が価値のある記録と考えるものはどれか。","options":["判断の経緯を再現できる記録","情報を可能な限り多く集めた記録","結論だけを短く残した記録","他人が読めない個人的な記録"],"answer":"判断の経緯を再現できる記録","explanationKo":"판단 과정을 재현할 수 있는 기록을 가치 있게 본다."},{"prompt":"採用しなかった案も残す理由は何か。","options":["条件が変わったときに判断を見直しやすいから","記録の量を増やせるから","結論を隠せるから","記憶する必要がなくなるから"],"answer":"条件が変わったときに判断を見直しやすいから","explanationKo":"조건이 변했을 때 판단을 다시 검토하기 쉬워진다."},{"prompt":"本文でいう記録の役割は何か。","options":["将来の判断更新を助けること","過去の判断を永久に固定すること","すべてを暗記させること","情報検索を不要にすること"],"answer":"将来の判断更新を助けること","explanationKo":"기록은 미래의 판단 갱신을 돕는 단서이다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0165","prompt":"「統合」の読み方として最も適切なものを選びなさい。","options":["てきせい","がっぺい","とうごう","げんろん"],"answer":"とうごう","explanationKo":"「統合」는 「とうごう」라고 읽는다. 뜻은 통합이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1137","prompt":"「掲げる」の読み方として最も適切なものを選びなさい。","options":["となえる","かかげる","ひきいる","たずさわる"],"answer":"かかげる","explanationKo":"「掲げる」는 「かかげる」라고 읽는다. 뜻은 내걸다; 내세우다; 제시하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0377","prompt":"「無用」の読み方として最も適切なものを選びなさい。","options":["むよう","むこう","とぼしい","ふかけつ"],"answer":"むよう","explanationKo":"「無用」는 「むよう」라고 읽는다. 뜻은 무용; 불필요; 쓸모없음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0166","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n裁判所は双方の主張と証拠を検討した上で、来月（　）を言い渡す予定だ。","options":["放棄","妥協","公募","判決"],"answer":"判決","explanationKo":"문맥상 「判決」가 가장 자연스럽다. 판결라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
