INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1138","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n祖父はこの町で長年、小さな商店を（　）ことを続けてきた。","options":["促す","営む","脅す","緩める"],"answer":"営む","explanationKo":"문맥상 「営む」가 가장 자연스럽다. 영위하다; 운영하다; 치르다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0171","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n両国は安全保障上の協力を強化するため、新たな（　）関係を結んだ。","options":["同盟","特権","主観","良識"],"answer":"同盟","explanationKo":"문맥상 「同盟」가 가장 자연스럽다. 동맹라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0412","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n問題が起きたときほど、事実を隠さず（　）に説明する姿勢が信頼につながる。","options":["疎か","一概に","厳密","誠実"],"answer":"誠実","explanationKo":"문맥상 「誠実」가 가장 자연스럽다. 성실; 진실됨; 성의 있음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0173","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n働き方の多様化に伴い、雇用の（　）も以前より複雑になっている。","options":["情勢","言論","形態","一連"],"answer":"形態","explanationKo":"문맥상 「形態」가 가장 자연스럽다. 형태; 형식라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0174","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの金額を超える契約は、部長の（　）だけでは承認できない。","options":["分離","権限","知性","覆面"],"answer":"権限","explanationKo":"문맥상 「権限」가 가장 자연스럽다. 권한라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1185","prompt":"「仕事・研究・事業などに関係して、その活動に参加する。」という意味に最も近い語を選びなさい。","options":["携わる","緩む","膨れる","慎む"],"answer":"携わる","explanationKo":"「携わる」의 핵심 의미는 종사하다; 관여하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0417","prompt":"「恐れずに思い切って行動するさま。また、発想や変更の規模が大きいさま。」という意味に最も近い語を選びなさい。","options":["著しい","無効","乏しい","大胆"],"answer":"大胆","explanationKo":"「大胆」의 핵심 의미는 대담; 과감이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0176","prompt":"「必要な物や情報などを手に入れること。」という意味に最も近い語を選びなさい。","options":["経緯","方策","入手","職務"],"answer":"入手","explanationKo":"「入手」의 핵심 의미는 입수; 획득이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0177","prompt":"「専門的な知識・実績・地位などによって、他者から高い信頼や影響力を認められていること。また、その人や機関。」という意味に最も近い語を選びなさい。","options":["権限","権威","論議","滞納"],"answer":"権威","explanationKo":"「権威」의 핵심 의미는 권위; 권위자이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1386","prompt":"「好ましくない責任・処罰・危険・被害などを受けずに済む。」という意味に最も近い語を選びなさい。","options":["免れる","覆す","顧みる","脅かす"],"answer":"免れる","explanationKo":"「免れる」의 핵심 의미는 면하다; 모면하다; 벗어나다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','grammar',1,'〜たところで','{"pattern":"〜たところで","meaningKo":"〜해 보아도","explanation":"〜たところで는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今さら言い訳をしたところで、失った信頼がすぐ戻るわけではない。","ko":"문맥에서 〜해 보아도의 의미로 쓰였다."},{"ja":"一人で考えたところで解決しないのだから、専門家に相談した方がよい。","ko":"이 문장도 〜해 보아도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','grammar',2,'〜だに','{"pattern":"〜だに","meaningKo":"〜하기만 해도","explanation":"〜だに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"事故当時の状況は、想像するだに恐ろしい。","ko":"문맥에서 〜하기만 해도의 의미로 쓰였다."},{"ja":"故郷を離れる日のことは、考えるだに寂しくなる。","ko":"이 문장도 〜하기만 해도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今さら言い訳をし（　）、失った信頼がすぐ戻るわけではない。","options":["〜を皮切りに","〜たところで","〜てやまない","〜に即して"],"answer":"〜たところで","explanationKo":"문맥상 〜해 보아도를 나타내는 「〜たところで」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n事故当時の状況は、想像する（　）恐ろしい。","options":["〜だに","〜とあって","〜にたえる","〜を禁じ得ない"],"answer":"〜だに","explanationKo":"문맥상 〜하기만 해도를 나타내는 「〜だに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n限られた予算なので、一円（　）無駄にはできない。","options":["〜とあれば","〜に足る","〜をものともせず","〜たりとも"],"answer":"〜たりとも","explanationKo":"문맥상 단 하나라도를 나타내는 「〜たりとも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-04','reading',1,'多数決の前に','{"passage":"多数決は意見の対立を処理する便利な方法だが、議論を省略する道具ではない。選択肢が十分に整理されず、少数意見が示した問題点も検討されないまま票を数えれば、決定は速くても納得は得にくい。投票前の議論には、全員を同じ意見にするのではなく、何を優先し、どの不利益を受け入れるのかを明らかにする役割がある。その共有があれば、反対した人も決定の根拠を理解し、実行段階で協力しやすくなる。","questions":[{"prompt":"筆者は多数決の前に何が必要だと述べているか。","options":["優先事項と不利益を明らかにする議論","全員を同じ意見にする説得","少数意見を除外する手続き","選択肢を一つに限定すること"],"answer":"優先事項と不利益を明らかにする議論","explanationKo":"우선사항과 감수할 불이익을 밝히는 논의가 필요하다."},{"prompt":"投票前の議論の目的ではないものはどれか。","options":["全員の意見を完全に一致させること","選択肢を整理すること","少数意見の問題点を検討すること","決定の根拠を共有すること"],"answer":"全員の意見を完全に一致させること","explanationKo":"모든 사람의 의견을 완전히 같게 만드는 것이 목적은 아니다."},{"prompt":"根拠が共有されると期待できることは何か。","options":["反対者も実行に協力しやすくなる","投票そのものが不要になる","不利益が完全になくなる","少数意見が多数意見に変わる"],"answer":"反対者も実行に協力しやすくなる","explanationKo":"결정 근거를 이해하면 반대자도 실행에 협력하기 쉬워진다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0182","prompt":"「対抗」の読み方として最も適切なものを選びなさい。","options":["しゅほう","げんろん","てきせい","たいこう"],"answer":"たいこう","explanationKo":"「対抗」는 「たいこう」라고 읽는다. 뜻은 대항; 맞서 경쟁함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1398","prompt":"「募る」の読み方として最も適切なものを選びなさい。","options":["おう","ごまかす","つのる","たえる"],"answer":"つのる","explanationKo":"「募る」는 「つのる」라고 읽는다. 뜻은 모집하다; 모으다; 점점 심해지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0456","prompt":"「不当」の読み方として最も適切なものを選びなさい。","options":["たんどく","ふとう","ふかけつ","いっさい"],"answer":"ふとう","explanationKo":"「不当」는 「ふとう」라고 읽는다. 뜻은 부당; 정당하지 않음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0183","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n製品に不具合が見つかり、メーカーは対象商品を自主（　）すると発表した。","options":["回収","宣言","放棄","妥協"],"answer":"回収","explanationKo":"문맥상 「回収」가 가장 자연스럽다. 회수; 수거라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0186","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの薬には炎症を抑える（　）があるが、副作用にも注意が必要だ。","options":["緩和","拒絶","民族","作用"],"answer":"作用","explanationKo":"문맥상 「作用」가 가장 자연스럽다. 작용; 영향라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1494","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n冗談のつもりでも、相手を（　）ような発言は避けるべきだ。","options":["覆す","制する","脅かす","紛れる"],"answer":"脅かす","explanationKo":"문맥상 「脅かす」가 가장 자연스럽다. 겁주다; 위협하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0189","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n住民は突然の計画変更に（　）し、自治体に説明を求めた。","options":["主観","抗議","福祉","特権"],"answer":"抗議","explanationKo":"문맥상 「抗議」가 가장 자연스럽다. 항의라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0472","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n改善につなげたいので、この企画について（　）な意見を聞かせてください。","options":["率直","厳密","敢えて","無効"],"answer":"率直","explanationKo":"문맥상 「率直」가 가장 자연스럽다. 솔직; 거리낌 없음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0190","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n申請内容に誤りがないか、（　）事項を提出前にもう一度確認してください。","options":["対処","武装","反乱","記載"],"answer":"記載","explanationKo":"문맥상 「記載」가 가장 자연스럽다. 기재; 기록라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0193","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n動画が正常に（　）できない場合は、通信環境を確認してください。","options":["合意","主催","再生","雇用"],"answer":"再生","explanationKo":"문맥상 「再生」가 가장 자연스럽다. 재생; 재생시키기; 회복라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1808","prompt":"「集団・組織・部下などの先頭に立って統率し、導く。」という意味に最も近い語を選びなさい。","options":["緩む","率いる","隔たる","負う"],"answer":"率いる","explanationKo":"「率いる」의 핵심 의미는 이끌다; 거느리다; 지휘하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0528","prompt":"「予想どおりの結果になったことを示す語。また、疑問文で『本当に〜だろうか』という強い疑いを表す。」という意味に最も近い語を選びなさい。","options":["果たして","著しい","独自","厳密"],"answer":"果たして","explanationKo":"「果たして」의 핵심 의미는 과연; 정말; 도대체이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0194","prompt":"「学習や経験によらず、生物が生まれつき備えている行動の傾向や能力。」という意味に最も近い語を選びなさい。","options":["接触","協定","進展","本能"],"answer":"本能","explanationKo":"「本能」의 핵심 의미는 본능이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0195","prompt":"「人をある国・地域・組織・集団などから強制的に追い出すこと。」という意味に最も近い語を選びなさい。","options":["規範","過疎","追放","事前"],"answer":"追放","explanationKo":"「追放」의 핵심 의미는 추방; 축출이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1897","prompt":"「相手に行動するよう働きかける。また、物事の進行・発達・変化を早める。」という意味に最も近い語を選びなさい。","options":["滅ぼす","促す","携わる","掲げる"],"answer":"促す","explanationKo":"「促す」의 핵심 의미는 촉구하다; 재촉하다; 촉진하다; 권하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','grammar',1,'〜たりとも','{"pattern":"〜たりとも","meaningKo":"단 하나라도","explanation":"〜たりとも는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"試験中は一秒たりとも気を抜くことができなかった。","ko":"문맥에서 단 하나라도의 의미로 쓰였다."},{"ja":"限られた予算なので、一円たりとも無駄にはできない。","ko":"이 문장도 단 하나라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','grammar',2,'〜であれ','{"pattern":"〜であれ","meaningKo":"〜라 할지라도","explanation":"〜であれ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"どのような事情であれ、事実を意図的に隠すことは許されない。","ko":"문맥에서 〜라 할지라도의 의미로 쓰였다."},{"ja":"相手が誰であれ、礼儀をもって接するべきだ。","ko":"이 문장도 〜라 할지라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n試験中は一秒（　）気を抜くことができなかった。","options":["〜たりとも","〜とあれば","〜に足る","〜をものともせず"],"answer":"〜たりとも","explanationKo":"문맥상 단 하나라도를 나타내는 「〜たりとも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nどのような事情（　）、事実を意図的に隠すことは許されない。","options":["〜といえども","〜にもまして","〜あっての","〜であれ"],"answer":"〜であれ","explanationKo":"문맥상 〜라 할지라도를 나타내는 「〜であれ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n在宅勤務を始め（　）、生活のリズムが大きく変わった。","options":["〜ばこそ","〜いかんでは","〜てからというもの","〜なくして"],"answer":"〜てからというもの","explanationKo":"문맥상 〜하고 나서부터 줄곧를 나타내는 「〜てからというもの」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-05','reading',1,'失敗を共有する条件','{"passage":"組織が失敗から学ぶには、失敗を報告しやすい雰囲気が必要だと言われる。しかし、何を報告しても責任が問われない仕組みにすればよいわけではない。隠蔽や故意の違反と、十分注意しても避けられなかった試行上の失敗は区別されるべきだ。区別の基準が明確であれば、報告者は不当に処罰される不安を減らせる一方、組織も規律を保てる。安心と責任は対立するのではなく、透明な基準によって両立させるものだ。","questions":[{"prompt":"筆者が必要だと考えるものは何か。","options":["失敗の性質を区別する透明な基準","すべての失敗を免責する制度","違反を報告しない自由","報告者を必ず処罰する規則"],"answer":"失敗の性質を区別する透明な基準","explanationKo":"실패의 성격을 구분하는 투명한 기준이 필요하다."},{"prompt":"区別されるべきものはどれか。","options":["故意の違反と避けにくい試行上の失敗","報告者と管理者の年齢","成功した部署と失敗した部署の人数","短い報告と長い報告"],"answer":"故意の違反と避けにくい試行上の失敗","explanationKo":"고의 위반과 피하기 어려웠던 시행상의 실패를 구분해야 한다."},{"prompt":"本文の内容と合うものはどれか。","options":["安心と責任は明確な基準で両立できる","責任を問えば学習は不可能になる","報告しやすさには規律が不要だ","失敗はすべて同じように扱うべきだ"],"answer":"安心と責任は明確な基準で両立できる","explanationKo":"안심과 책임은 명확한 기준을 통해 양립할 수 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-06','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0200","prompt":"「推測」の読み方として最も適切なものを選びなさい。","options":["すいそく","しょうにん","しゅほう","げんろん"],"answer":"すいそく","explanationKo":"「推測」는 「すいそく」라고 읽는다. 뜻은 추측; 추정이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
