INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-06','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0201","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n軍の一部が政府に対して（　）を起こし、首都では緊張が高まった。","options":["放棄","反乱","追放","宣言"],"answer":"反乱","explanationKo":"문맥상 「反乱」가 가장 자연스럽다. 반란; 반역라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
