INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-06','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1244","prompt":"「改めて言うまでもなく、当然。」という意味に最も近い語を選びなさい。","options":["不当","無論","厳密","甚だ"],"answer":"無論","explanationKo":"「無論」의 핵심 의미는 물론; 말할 것도 없이이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-06','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0209","prompt":"「国と国との領土を分ける境界。『こっきょう』とも読む。」という意味に最も近い語を選びなさい。","options":["国境","抗議","接触","協定"],"answer":"国境","explanationKo":"「国境」의 핵심 의미는 국경; 나라 사이의 경계이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-06','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0210","prompt":"「物理的に押す力。また、人や組織に特定の行動を取らせようとする強い働きかけ。」という意味に最も近い語を選びなさい。","options":["実践","促進","論議","圧力"],"answer":"圧力","explanationKo":"「圧力」의 핵심 의미는 압력; 압박이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
