INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-06','grammar',1,'〜てからというもの','{"pattern":"〜てからというもの","meaningKo":"〜하고 나서부터 줄곧","explanation":"〜てからというもの는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"子どもが生まれてからというもの、時間の使い方を強く意識するようになった。","ko":"문맥에서 〜하고 나서부터 줄곧의 의미로 쓰였다."},{"ja":"在宅勤務を始めてからというもの、生活のリズムが大きく変わった。","ko":"이 문장도 〜하고 나서부터 줄곧의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-06','grammar',2,'〜てやまない','{"pattern":"〜てやまない","meaningKo":"진심으로 계속 〜하다","explanation":"〜てやまない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"被災地が一日も早く復興することを願ってやまない。","ko":"문맥에서 진심으로 계속 〜하다의 의미로 쓰였다."},{"ja":"若い研究者の今後の活躍を期待してやまない。","ko":"이 문장도 진심으로 계속 〜하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-06','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n子どもが生まれ（　）、時間の使い方を強く意識するようになった。","options":["〜なくして","〜ばこそ","〜いかんでは","〜てからというもの"],"answer":"〜てからというもの","explanationKo":"문맥상 〜하고 나서부터 줄곧를 나타내는 「〜てからというもの」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-06','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n被災地が一日も早く復興することを願っ（　）。","options":["〜べからず","〜いかんにかかわらず","〜てやまない","〜ならでは"],"answer":"〜てやまない","explanationKo":"문맥상 진심으로 계속 〜하다를 나타내는 「〜てやまない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-06','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n人気作家の講演会（　）、会場には大勢の人が集まった。","options":["〜ずにはおかない","〜とあって","〜に即して","〜までもない"],"answer":"〜とあって","explanationKo":"문맥상 〜라는 특별한 상황이라를 나타내는 「〜とあって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-06','reading',1,'便利な指標の落とし穴','{"passage":"数値は比較を容易にするが、測りやすいものだけが重要だという錯覚も生む。例えば問い合わせへの応答時間を短くする目標を設けると、担当者は早く返信するようになる。しかし、問題が解決したかを評価しなければ、中身のない返事が増えるかもしれない。指標が行動を変える以上、測定対象だけでなく、その指標から漏れる価値も確認しなければならない。良い指標とは、完全な答えではなく、現場を観察するための一つの窓である。","questions":[{"prompt":"応答時間だけを評価した場合の問題は何か。","options":["解決につながらない返事が増える可能性がある","担当者が返信しなくなる","問い合わせの数が必ず減る","数値で比較できなくなる"],"answer":"解決につながらない返事が増える可能性がある","explanationKo":"해결로 이어지지 않는 형식적인 답변이 늘 수 있다."},{"prompt":"指標を使う際に確認すべきものは何か。","options":["指標から漏れる価値","数値の大きさだけ","担当者の好みだけ","過去の目標だけ"],"answer":"指標から漏れる価値","explanationKo":"지표에 잡히지 않는 가치도 확인해야 한다."},{"prompt":"筆者は良い指標を何に例えているか。","options":["現場を見るための一つの窓","完全な答え","変更できない規則","作業を代行する機械"],"answer":"現場を見るための一つの窓","explanationKo":"좋은 지표는 현장을 관찰하는 하나의 창이다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0215","prompt":"「確信」の読み方として最も適切なものを選びなさい。","options":["しゅほう","かくしん","けいたい","しょうにん"],"answer":"かくしん","explanationKo":"「確信」는 「かくしん」라고 읽는다. 뜻은 확신이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
