INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0226","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n制度上は任意とされているが、（　）的には全員の参加が求められている。","options":["実質","連邦","余地","本質"],"answer":"実質","explanationKo":"문맥상 「実質」가 가장 자연스럽다. 실질; 실제 내용라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2213","prompt":"「怖い言葉・態度などで相手に恐怖を与え、従わせようとする。」という意味に最も近い語を選びなさい。","options":["堪える","逸らす","準ずる","脅す"],"answer":"脅す","explanationKo":"「脅す」의 핵심 의미는 위협하다; 협박하다; 겁주다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1953","prompt":"「困難・反対・必要性の低さなどを承知のうえで、それでも意図的に行うさま。」という意味に最も近い語を選びなさい。","options":["果たして","誠実","敢えて","不当"],"answer":"敢えて","explanationKo":"「敢えて」의 핵심 의미는 굳이; 감히; 일부러이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0228","prompt":"「制度・システム・資金などを目的に沿って実際に使い、管理すること。」という意味に最も近い語を選びなさい。","options":["権威","運用","制裁","欠乏"],"answer":"運用","explanationKo":"「運用」의 핵심 의미는 운용; 운영이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0229","prompt":"「国家や地域を政治的な権力によって治め、秩序を維持すること。」という意味に最も近い語を選びなさい。","options":["統治","原則","人格","事前"],"answer":"統治","explanationKo":"「統治」의 핵심 의미는 통치; 지배이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2218","prompt":"「視線・注意・方向などを別のほうへ向ける。」という意味に最も近い語を選びなさい。","options":["携わる","掲げる","滅ぼす","逸らす"],"answer":"逸らす","explanationKo":"「逸らす」의 핵심 의미는 돌리다; 피하다; 비껴가게 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','grammar',1,'〜とあって','{"pattern":"〜とあって","meaningKo":"〜라는 특별한 상황이라","explanation":"〜とあって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"連休初日とあって、駅は朝から旅行客で混雑していた。","ko":"문맥에서 〜라는 특별한 상황이라의 의미로 쓰였다."},{"ja":"人気作家の講演会とあって、会場には大勢の人が集まった。","ko":"이 문장도 〜라는 특별한 상황이라의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','grammar',2,'〜とあれば','{"pattern":"〜とあれば","meaningKo":"〜라면","explanation":"〜とあれば는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"家族の安全のためとあれば、多少の出費は惜しまない。","ko":"문맥에서 〜라면의 의미로 쓰였다."},{"ja":"地域の復興に役立つとあれば、喜んで協力したい。","ko":"이 문장도 〜라면의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n連休初日（　）、駅は朝から旅行客で混雑していた。","options":["〜までもない","〜ずにはおかない","〜とあって","〜に即して"],"answer":"〜とあって","explanationKo":"문맥상 〜라는 특별한 상황이라를 나타내는 「〜とあって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n家族の安全のため（　）、多少の出費は惜しまない。","options":["〜ずにはすまない","〜とあれば","〜にたえる","〜もさることながら"],"answer":"〜とあれば","explanationKo":"문맥상 〜라면를 나타내는 「〜とあれば」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n小さなミス（　）、重大事故につながる可能性がある。","options":["〜といえども","〜に足る","〜を皮切りに","〜そばから"],"answer":"〜といえども","explanationKo":"문맥상 〜라 할지라도를 나타내는 「〜といえども」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-07','reading',1,'地域文化を残すということ','{"passage":"地域文化の保存というと、昔の形をそのまま守ることだと思われがちだ。しかし、行事や技術は、人々が暮らしの中で使い続けてきたからこそ残った。環境が変わっても一切変えてはならないとすれば、担い手の負担が増え、かえって継続できなくなる場合がある。何を変えてよく、何を失えばその文化ではなくなるのかを話し合うことが必要だ。保存とは変化を拒むことではなく、核心を選び直しながら次の世代へ渡す営みである。","questions":[{"prompt":"筆者の考える文化の保存とは何か。","options":["核心を選び直しながら継承すること","昔の形を一切変えないこと","担い手の負担を増やすこと","行事を生活から切り離すこと"],"answer":"核心を選び直しながら継承すること","explanationKo":"핵심을 다시 선택하면서 다음 세대로 계승하는 것이다."},{"prompt":"昔の形を完全に固定した場合、何が起こり得るか。","options":["負担が増えて継続が難しくなる","文化の利用者が必ず増える","環境の変化が止まる","話し合いが不要になる"],"answer":"負担が増えて継続が難しくなる","explanationKo":"담당자의 부담이 늘어 지속하기 어려워질 수 있다."},{"prompt":"話し合う必要があることは何か。","options":["変えられる部分と守るべき核心","昔の資料の量だけ","参加者の年齢だけ","行事の開催回数だけ"],"answer":"変えられる部分と守るべき核心","explanationKo":"바꿀 수 있는 부분과 지켜야 할 핵심을 논의해야 한다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0240","prompt":"「合意」の読み方として最も適切なものを選びなさい。","options":["けいたい","しょうにん","ごうい","ちょうしゅう"],"answer":"ごうい","explanationKo":"「合意」는 「ごうい」라고 읽는다. 뜻은 합의; 의견 일치이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2228","prompt":"「躊躇う」の読み方として最も適切なものを選びなさい。","options":["とりくむ","ためらう","ほろぼす","つかえる"],"answer":"ためらう","explanationKo":"「躊躇う」는 「ためらう」라고 읽는다. 뜻은 망설이다; 주저하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2105","prompt":"「疎か」の読み方として最も適切なものを選びなさい。","options":["おろそか","まぎらわしい","げんみつ","はなはだ"],"answer":"おろそか","explanationKo":"「疎か」는 「おろそか」라고 읽는다. 뜻은 소홀함; 등한함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0241","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n結論だけでなく、そこに至る（　）を明確に説明しなければ相手は納得しない。","options":["世代","根本","様式","論理"],"answer":"論理","explanationKo":"문맥상 「論理」가 가장 자연스럽다. 논리라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
