INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2323","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長く使っているうちに、ねじが少し（　）ことがある。","options":["脅かす","緩む","慎む","緩める"],"answer":"緩む","explanationKo":"문맥상 「緩む」가 가장 자연스럽다. 느슨해지다; 풀리다; 완화되다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0247","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n契約書の原本は、規定に従って施錠できる場所に（　）してください。","options":["保管","論議","滞納","権限"],"answer":"保管","explanationKo":"문맥상 「保管」가 가장 자연스럽다. 보관; 보존라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-2154","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその説明は（　）不十分だ。","options":["一概に","率直","無論","甚だ"],"answer":"甚だ","explanationKo":"문맥상 「甚だ」가 가장 자연스럽다. 매우; 몹시; 심히라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0249","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n会社は（　）の不祥事について調査結果を公表し、再発防止策を示した。","options":["正規","抑圧","一連","侵略"],"answer":"一連","explanationKo":"문맥상 「一連」가 가장 자연스럽다. 일련; 연속된 한 묶음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0251","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n仕事の能力が高くても、他人の（　）を否定するような発言は許されない。","options":["実質","人格","荒廃","連邦"],"answer":"人格","explanationKo":"문맥상 「人格」가 가장 자연스럽다. 인격; 인품라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2324","prompt":"「締まっているものをゆるくする。また、速度・緊張・規制などを弱める。」という意味に最も近い語を選びなさい。","options":["緩める","滅ぼす","慕う","取り組む"],"answer":"緩める","explanationKo":"「緩める」의 핵심 의미는 느슨하게 하다; 늦추다; 완화하다; 풀다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2192","prompt":"「壊れやすく丈夫でない。また、精神的に弱い。」という意味に最も近い語を選びなさい。","options":["無効","動的","無用","脆い"],"answer":"脆い","explanationKo":"「脆い」의 핵심 의미는 부서지기 쉽다; 약하다; 여리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0252","prompt":"「事実について知っていることを述べたり、その事実を証明したりする人。」という意味に最も近い語を選びなさい。","options":["規制","抗議","証人","記述"],"answer":"証人","explanationKo":"「証人」의 핵심 의미는 증인이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0254","prompt":"「人々が安心して健康で文化的な生活を送れるよう、社会が生活や自立を支えること。また、その制度や施策。」という意味に最も近い語を選びなさい。","options":["実践","福祉","対抗","確信"],"answer":"福祉","explanationKo":"「福祉」의 핵심 의미는 복지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2494","prompt":"「ある基準・例に従う。また、それに相当する扱いをする。」という意味に最も近い語を選びなさい。","options":["準ずる","躊躇う","唱える","顧みる"],"answer":"準ずる","explanationKo":"「準ずる」의 핵심 의미는 준하다; 기준에 따르다; 그에 상응하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','grammar',1,'〜といえども','{"pattern":"〜といえども","meaningKo":"〜라 할지라도","explanation":"〜といえども는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"専門家といえども、将来を完全に予測することはできない。","ko":"문맥에서 〜라 할지라도의 의미로 쓰였다."},{"ja":"小さなミスといえども、重大事故につながる可能性がある。","ko":"이 문장도 〜라 할지라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','grammar',2,'〜なくして','{"pattern":"〜なくして","meaningKo":"〜없이는","explanation":"〜なくして는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"関係者の協力なくして、この大規模な調査は実現しなかった。","ko":"문맥에서 〜없이는의 의미로 쓰였다."},{"ja":"地道な努力なくして、技術の向上は望めない。","ko":"이 문장도 〜없이는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n専門家（　）、将来を完全に予測することはできない。","options":["〜そばから","〜といえども","〜に足る","〜を皮切りに"],"answer":"〜といえども","explanationKo":"문맥상 〜라 할지라도를 나타내는 「〜といえども」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n関係者の協力（　）、この大規模な調査は実現しなかった。","options":["〜なくして","〜にもまして","〜を禁じ得ない","〜たところで"],"answer":"〜なくして","explanationKo":"문맥상 〜없이는를 나타내는 「〜なくして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n四季の変化に富むこの地域（　）の景色を楽しめる。","options":["〜ばこそ","〜をものともせず","〜だに","〜ならでは"],"answer":"〜ならでは","explanationKo":"문맥상 〜이기에 가능한를 나타내는 「〜ならでは」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-08','reading',1,'予測と備え','{"passage":"将来を正確に予測できないから備えても無駄だ、という考え方がある。しかし備えの目的は、特定の未来を言い当てることではない。複数の事態を想定し、どの事態でも重大な損失を避けられる選択肢を持つことにある。予測が外れたときに計画が役に立たなくなるなら、その計画は予測に依存しすぎている。変化の兆候を観察し、前提が崩れた時点で計画を修正できる余地を残すことも、備えの一部なのである。","questions":[{"prompt":"筆者によれば、備えの目的は何か。","options":["複数の事態で重大な損失を避けること","未来を一つだけ正確に当てること","予測を変更しないこと","すべての損失を完全になくすこと"],"answer":"複数の事態で重大な損失を避けること","explanationKo":"여러 상황에서 중대한 손실을 피할 선택지를 갖는 것이 목적이다."},{"prompt":"役に立たない計画の特徴は何か。","options":["一つの予測に依存しすぎている","複数の事態を想定している","修正の余地を残している","変化の兆候を観察している"],"answer":"一つの予測に依存しすぎている","explanationKo":"하나의 예측에 지나치게 의존한 계획이다."},{"prompt":"備えの一部として本文が挙げるものは何か。","options":["前提が崩れたら修正できる余地","最初の計画を必ず守る意志","変化を無視する態度","損失を計算しないこと"],"answer":"前提が崩れたら修正できる余地","explanationKo":"전제가 무너지면 계획을 수정할 여지를 남겨야 한다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0261","prompt":"「資産」の読み方として最も適切なものを選びなさい。","options":["にんめい","かいしゅう","こうじょう","しさん"],"answer":"しさん","explanationKo":"「資産」는 「しさん」라고 읽는다. 뜻은 자산; 재산이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2534","prompt":"「慕う」の読み方として最も適切なものを選びなさい。","options":["おう","ごまかす","したう","たえる"],"answer":"したう","explanationKo":"「慕う」는 「したう」라고 읽는다. 뜻은 사모하다; 흠모하다; 그리워하다; 따르다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2366","prompt":"「一概に」の読み方として最も適切なものを選びなさい。","options":["おろそか","いちがいに","けいそつ","ちゅうじつ"],"answer":"いちがいに","explanationKo":"「一概に」는 「いちがいに」라고 읽는다. 뜻은 일률적으로; 무조건; 단정적으로이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0262","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n手術後の（　）は良好で、問題がなければ来週退院できる見込みだ。","options":["経過","規格","処分","達成"],"answer":"経過","explanationKo":"문맥상 「経過」가 가장 자연스럽다. 경과; 진행 과정; 시간의 흐름라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0266","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n改正された制度は来年四月から（　）される予定で、関係機関が準備を進めている。","options":["規制","抗議","接触","施行"],"answer":"施行","explanationKo":"문맥상 「施行」가 가장 자연스럽다. 시행; 실시라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2618","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n質問の核心を（　）ことなく、答えてください。","options":["阻む","制する","誤魔化す","紛れる"],"answer":"誤魔化す","explanationKo":"문맥상 「誤魔化す」가 가장 자연스럽다. 속이다; 얼버무리다; 속여 넘기다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0267","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n離職率が上がった（　）を特定するため、社員への匿名調査を実施した。","options":["作用","要因","非難","所属"],"answer":"要因","explanationKo":"문맥상 「要因」가 가장 자연스럽다. 요인; 원인 요소라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-2396","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）な発言で相手を傷つけてしまった。","options":["軽率","知的","厳か","多様"],"answer":"軽率","explanationKo":"문맥상 「軽率」가 가장 자연스럽다. 경솔함; 신중하지 못함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0270","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n成果に応じて（　）が決まる制度には、評価基準の透明性が欠かせない。","options":["転換","侵略","正規","報酬"],"answer":"報酬","explanationKo":"문맥상 「報酬」가 가장 자연스럽다. 보수; 대가; 사례라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0271","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n便利さという（　）だけでなく、個人情報保護の観点からもサービスを評価する必要がある。","options":["荒廃","連邦","側面","構想"],"answer":"側面","explanationKo":"문맥상 「側面」가 가장 자연스럽다. 측면; 일면; 옆면라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2675","prompt":"「他のものに混じって見分けにくくなる。また、別のことに気を取られて気がまぎれる。」という意味に最も近い語を選びなさい。","options":["緩む","紛れる","隔たる","負う"],"answer":"紛れる","explanationKo":"「紛れる」의 핵심 의미는 뒤섞이다; 구별하기 어려워지다; 다른 데 정신이 팔리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2639","prompt":"「生まれつき備わっているさま。」という意味に最も近い語を選びなさい。","options":["先天的","厳密","甚だ","不当"],"answer":"先天的","explanationKo":"「先天的」의 핵심 의미는 선천적이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0272","prompt":"「特定の人・企業・組織などが、利益・市場・権利などを一人または一社で占めること。」という意味に最も近い語を選びなさい。","options":["施行","占領","制裁","独占"],"answer":"独占","explanationKo":"「独占」의 핵심 의미는 독점이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0273","prompt":"「物事を見たり判断したりするときの立場や着目する点。」という意味に最も近い語を選びなさい。","options":["対抗","確信","観点","象徴"],"answer":"観点","explanationKo":"「観点」의 핵심 의미는 관점; 보는 입장이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2722","prompt":"「体積が増えてふくらむ。また、不満でふくれっ面になる。」という意味に最も近い語を選びなさい。","options":["免れる","膨れる","緩める","制する"],"answer":"膨れる","explanationKo":"「膨れる」의 핵심 의미는 부풀다; 붓다; 토라지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','grammar',1,'〜ならでは','{"pattern":"〜ならでは","meaningKo":"〜이기에 가능한","explanation":"〜ならでは는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"これは長年現場を経験した職人ならではの工夫だ。","ko":"문맥에서 〜이기에 가능한의 의미로 쓰였다."},{"ja":"四季の変化に富むこの地域ならではの景色を楽しめる。","ko":"이 문장도 〜이기에 가능한의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','grammar',2,'〜に即して','{"pattern":"〜に即して","meaningKo":"〜에 입각하여","explanation":"〜に即して는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"現場の実情に即して、作業手順を柔軟に見直す必要がある。","ko":"문맥에서 〜에 입각하여의 의미로 쓰였다."},{"ja":"法律の趣旨に即して制度を運用しなければならない。","ko":"이 문장도 〜에 입각하여의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこれは長年現場を経験した職人（　）の工夫だ。","options":["〜ならでは","〜ばこそ","〜をものともせず","〜だに"],"answer":"〜ならでは","explanationKo":"문맥상 〜이기에 가능한를 나타내는 「〜ならでは」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n現場の実情（　）、作業手順を柔軟に見直す必要がある。","options":["〜べからず","〜あっての","〜たりとも","〜に即して"],"answer":"〜に即して","explanationKo":"문맥상 〜에 입각하여를 나타내는 「〜に即して」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの映画は大人の鑑賞（　）完成度を備えている。","options":["〜いかんでは","〜であれ","〜にたえる","〜までもない"],"answer":"〜にたえる","explanationKo":"문맥상 〜할 가치가 있다를 나타내는 「〜にたえる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-09','reading',1,'説明の分かりやすさ','{"passage":"分かりやすい説明とは、内容を単純にすることではない。相手がすでに知っていることと、これから理解すべきことの間に橋を架けることである。専門用語を日常語に置き換えても、その背景にある関係が示されなければ、相手は言葉だけを覚えて誤って使うかもしれない。逆に、必要な用語を示した上で具体例と限界を説明すれば、多少難しくても応用できる理解につながる。易しい言葉の多さより、理解の道筋が見えることが重要だ。","questions":[{"prompt":"筆者のいう分かりやすい説明とは何か。","options":["既知の内容と新しい内容を結びつけること","専門用語をすべてなくすこと","内容を可能な限り短くすること","具体例だけを並べること"],"answer":"既知の内容と新しい内容を結びつけること","explanationKo":"이미 아는 내용과 새로 이해할 내용을 연결하는 것이다."},{"prompt":"日常語への置き換えだけでは不十分な理由は何か。","options":["背景の関係が分からず誤用する可能性があるから","文章が必ず長くなるから","専門家が読めなくなるから","具体例が多くなりすぎるから"],"answer":"背景の関係が分からず誤用する可能性があるから","explanationKo":"배경 관계를 이해하지 못해 말을 잘못 사용할 수 있다."},{"prompt":"応用できる理解につながる説明はどれか。","options":["必要な用語に具体例と限界を添える説明","易しい単語だけを使う説明","結論だけを示す説明","用語の暗記だけを求める説明"],"answer":"必要な用語に具体例と限界を添える説明","explanationKo":"필요한 용어와 함께 구체적인 예와 한계를 설명해야 응용할 수 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0279","prompt":"「本格」の読み方として最も適切なものを選びなさい。","options":["ほんかく","せつりつ","にんめい","かいしゅう"],"answer":"ほんかく","explanationKo":"「本格」는 「ほんかく」라고 읽는다. 뜻은 본격; 정통; 제대로 된 수준이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2733","prompt":"「隔たる」の読み方として最も適切なものを選びなさい。","options":["ほろぼす","つかえる","とりくむ","へだたる"],"answer":"へだたる","explanationKo":"「隔たる」는 「へだたる」라고 읽는다. 뜻은 떨어져 있다; 차이가 나다; 동떨어지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
