INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0281","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n利用者の（　）に立つと、機能の多さより操作の分かりやすさのほうが重要かもしれない。","options":["世代","視点","討論","公募"],"answer":"視点","explanationKo":"문맥상 「視点」가 가장 자연스럽다. 시점; 관점; 보는 입장라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0282","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n照明と音楽の（　）によって、同じ会場でもまったく違う雰囲気が生まれた。","options":["演出","記述","規制","抗議"],"answer":"演出","explanationKo":"문맥상 「演出」가 가장 자연스럽다. 연출; 효과적으로 꾸밈라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2895","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n待遇は正社員に（　）。","options":["築く","躊躇う","膨れる","準じる"],"answer":"準じる","explanationKo":"문맥상 「準じる」가 가장 자연스럽다. 준하다; 따르다; 적용하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0284","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n応募した（　）を聞かれたら、仕事内容と自分の経験を結び付けて説明するとよい。","options":["非難","所属","動機","証拠"],"answer":"動機","explanationKo":"문맥상 「動機」가 가장 자연스럽다. 동기; 계기라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0073","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）な働き方を認める制度が整い、社員が勤務時間を選びやすくなった。","options":["軽率","多様","動的","不当"],"answer":"多様","explanationKo":"문맥상 「多様」가 가장 자연스럽다. 다양함; 여러 가지임라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0288","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n経営が悪化した会社を（　）するため、事業の選択と集中が進められた。","options":["再建","受け入れ","余地","本質"],"answer":"再建","explanationKo":"문맥상 「再建」가 가장 자연스럽다. 재건; 재정비; 회복라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0289","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n国内市場が成熟したため、多くの企業が東南アジアへの（　）を検討している。","options":["視点","異論","用件","進出"],"answer":"進出","explanationKo":"문맥상 「進出」가 가장 자연스럽다. 진출라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2903","prompt":"「苦痛・困難などを我慢して持ちこたえる。また、ある役目に耐え得る。」という意味に最も近い語を選びなさい。","options":["慕う","取り組む","堪える","滅ぼす"],"answer":"堪える","explanationKo":"「堪える」의 핵심 의미는 견디다; 참다; 감당하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0290","prompt":"「一定の形式や方法。また、時代・文化・分野などに共通して見られる表現上の特徴。」という意味に最も近い語を選びなさい。","options":["途上","様式","農地","報酬"],"answer":"様式","explanationKo":"「様式」의 핵심 의미는 양식; 형식; 방식이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0292","prompt":"「権利・責任・所有物・計画など、自分が持っていたものや行おうとしていたことを捨てること。」という意味に最も近い語を選びなさい。","options":["放棄","決断","施行","占領"],"answer":"放棄","explanationKo":"「放棄」의 핵심 의미는 포기; 방기; 권리 등을 버림이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0293","prompt":"「行事・大会・会合などを責任を持って企画し、中心となって開催すること。」という意味に最も近い語を選びなさい。","options":["侵略","悲観","譲歩","主催"],"answer":"主催","explanationKo":"「主催」의 핵심 의미는 주최; 주관이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0294","prompt":"「生活・労働などのために自国を離れて他国へ移り住むこと。また、その人。」という意味に最も近い語を選びなさい。","options":["争い","品質","移民","停滞"],"answer":"移民","explanationKo":"「移民」의 핵심 의미는 이민; 이민자이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','grammar',1,'〜にたえる','{"pattern":"〜にたえる","meaningKo":"〜할 가치가 있다","explanation":"〜にたえる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"長年の調査に基づくこの報告書は、十分検討にたえる内容だ。","ko":"문맥에서 〜할 가치가 있다의 의미로 쓰였다."},{"ja":"この映画は大人の鑑賞にもたえる完成度を備えている。","ko":"이 문장도 〜할 가치가 있다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','grammar',2,'〜に足る','{"pattern":"〜に足る","meaningKo":"〜할 만하다","explanation":"〜に足る는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"その研究成果は、国際的にも評価に足るものだ。","ko":"문맥에서 〜할 만하다의 의미로 쓰였다."},{"ja":"彼は重要な情報を任せるに足る信頼できる人物だ。","ko":"이 문장도 〜할 만하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長年の調査に基づくこの報告書は、十分検討（　）内容だ。","options":["〜までもない","〜いかんでは","〜であれ","〜にたえる"],"answer":"〜にたえる","explanationKo":"문맥상 〜할 가치가 있다를 나타내는 「〜にたえる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nその研究成果は、国際的にも評価（　）ものだ。","options":["〜いかんにかかわらず","〜てからというもの","〜に足る","〜もさることながら"],"answer":"〜に足る","explanationKo":"문맥상 〜할 만하다를 나타내는 「〜に足る」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n試合の結果（　）、最後まで諦めない姿勢が印象に残った。","options":["〜てやまない","〜にもまして","〜を皮切りに","〜ずにはおかない"],"answer":"〜にもまして","explanationKo":"문맥상 〜보다도 더욱를 나타내는 「〜にもまして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-10','reading',1,'合意を急がない','{"passage":"会議で早く合意することは、必ずしも効率的とは限らない。参加者が反対を口にしない理由は、納得したからではなく、情報不足や立場への遠慮かもしれない。そのまま実行に移れば、後になって前提の違いが表面化し、修正に大きな費用がかかる。合意を確認するときは賛否だけでなく、各自が何を事実として理解し、どの条件なら判断を変えるのかを尋ねるべきだ。短い異論の時間が、長い手戻りを防ぐこともある。","questions":[{"prompt":"参加者が反対しない理由として本文にないものはどれか。","options":["必ず十分に納得していること","情報が不足していること","立場に遠慮していること","前提を共有できていない可能性"],"answer":"必ず十分に納得していること","explanationKo":"반대하지 않는다고 반드시 충분히 납득한 것은 아니다."},{"prompt":"合意確認で尋ねるべきことは何か。","options":["理解している事実と判断が変わる条件","賛成か反対かだけ","会議時間の希望だけ","参加者の役職だけ"],"answer":"理解している事実と判断が変わる条件","explanationKo":"각자가 이해한 사실과 판단을 바꿀 조건을 물어야 한다."},{"prompt":"筆者が短い異論の時間を評価する理由は何か。","options":["後の大きな手戻りを防げるから","会議を必ず長くできるから","反対者を特定できるから","情報を減らせるから"],"answer":"後の大きな手戻りを防げるから","explanationKo":"짧은 이견 검토가 나중의 큰 재작업을 막을 수 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0303","prompt":"「紛争」の読み方として最も適切なものを選びなさい。","options":["せいやく","ふんそう","てんかん","しんりゃく"],"answer":"ふんそう","explanationKo":"「紛争」는 「ふんそう」라고 읽는다. 뜻은 분쟁; 갈등이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
