INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0309","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n物価の上昇に（　）の伸びが追いつかなければ、実質的な生活水準は下がる。","options":["賃金","領域","要因","領土"],"answer":"賃金","explanationKo":"문맥상 「賃金」가 가장 자연스럽다. 임금; 노동의 대가라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0316","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n国際（　）が急速に変化しているため、事業計画を柔軟に見直す必要がある。","options":["経緯","証拠","非難","情勢"],"answer":"情勢","explanationKo":"문맥상 「情勢」가 가장 자연스럽다. 정세; 상황; 형세라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0319","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nトラブルを防ぐため、変更内容は利用者に（　）に通知してください。","options":["導入","総合","事前","良識"],"answer":"事前","explanationKo":"문맥상 「事前」가 가장 자연스럽다. 사전; 미리라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0333","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n従来とは異なる分析（　）を使うことで、見落としていた傾向が明らかになった。","options":["転換","手法","証言","掲載"],"answer":"手法","explanationKo":"문맥상 「手法」가 가장 자연스럽다. 수법; 기법; 방법라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0334","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n役職を私的な（　）のように扱う姿勢は、組織への信頼を損なう。","options":["特権","保管","阻止","構想"],"answer":"特権","explanationKo":"문맥상 「特権」가 가장 자연스럽다. 특권; 특별한 권리라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0342","prompt":"「ある出来事が現在の状態に至るまでの事情や過程。『けいい』とも読む。」という意味に最も近い語を選びなさい。","options":["妥協","妨害","事項","経緯"],"answer":"経緯","explanationKo":"「経緯」의 핵심 의미는 경위; 자초지종; 일이 진행된 과정이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0344","prompt":"「本来は直接の当事者でない人・組織・国家などが、他者の問題や関係に入り込み影響を与えること。」という意味に最も近い語を選びなさい。","options":["任命","回収","介入","設立"],"answer":"介入","explanationKo":"「介入」의 핵심 의미는 개입; 관여이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0345","prompt":"「条件・資料・証明書・考えなどを相手に示して見せること。」という意味に最も近い語を選びなさい。","options":["施行","提示","悪化","決断"],"answer":"提示","explanationKo":"「提示」의 핵심 의미는 제시; 보여 줌이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0348","prompt":"「物事や交渉・研究などが前の段階から進み、新しい展開を見せること。」という意味に最も近い語を選びなさい。","options":["進展","解除","確定","悲観"],"answer":"進展","explanationKo":"「進展」의 핵심 의미는 진전; 발전이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0356","prompt":"「厳しさ・緊張・痛み・規制・条件などの程度を弱め、穏やかにすること。」という意味に最も近い語を選びなさい。","options":["立法","停滞","争い","緩和"],"answer":"緩和","explanationKo":"「緩和」의 핵심 의미는 완화; 누그러뜨림이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','grammar',1,'〜にもまして','{"pattern":"〜にもまして","meaningKo":"〜보다도 더욱","explanation":"〜にもまして는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今年は昨年にもまして、外国からの観光客が増えている。","ko":"문맥에서 〜보다도 더욱의 의미로 쓰였다."},{"ja":"試合の結果にもまして、最後まで諦めない姿勢が印象に残った。","ko":"이 문장도 〜보다도 더욱의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','grammar',2,'〜ばこそ','{"pattern":"〜ばこそ","meaningKo":"바로 〜이기 때문에","explanation":"〜ばこそ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"信頼していればこそ、問題点も率直に指摘するのだ。","ko":"문맥에서 바로 〜이기 때문에의 의미로 쓰였다."},{"ja":"将来を大切に思えばこそ、今は厳しい判断も必要になる。","ko":"이 문장도 바로 〜이기 때문에의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今年は昨年（　）、外国からの観光客が増えている。","options":["〜ずにはおかない","〜てやまない","〜にもまして","〜を皮切りに"],"answer":"〜にもまして","explanationKo":"문맥상 〜보다도 더욱를 나타내는 「〜にもまして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n信頼していれ（　）、問題点も率直に指摘するのだ。","options":["〜とあって","〜ばこそ","〜を禁じ得ない","〜ずにはすまない"],"answer":"〜ばこそ","explanationKo":"문맥상 바로 〜이기 때문에를 나타내는 「〜ばこそ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n関係者以外、ここに立ち入る（　）。","options":["〜べからず","〜をものともせず","〜そばから","〜とあれば"],"answer":"〜べからず","explanationKo":"문맥상 〜해서는 안 된다를 나타내는 「〜べからず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-11','reading',1,'学び直しの意味','{"passage":"一度学んだことを忘れると、最初からやり直しだと感じる。しかし、思い出せない状態と、何も学んでいない状態は同じではない。以前理解した内容は、適切な手掛かりに触れると再び結びつきやすく、二度目の学習では重要な点と不要な点を区別しやすい。忘却は学習の失敗を示すだけでなく、どの知識が孤立し、どの場面で使えないかを教える。学び直しとは過去を繰り返すことではなく、知識のつながりを組み替える機会なのである。","questions":[{"prompt":"筆者によれば、思い出せない状態にはどんな特徴があるか。","options":["手掛かりによって知識が再び結びつく可能性がある","何も学んでいない状態と完全に同じだ","二度目も重要点を区別できない","過去の理解は必ず消えている"],"answer":"手掛かりによって知識が再び結びつく可能性がある","explanationKo":"단서를 통해 이전 지식이 다시 연결될 수 있다."},{"prompt":"忘却から分かることは何か。","options":["孤立して使えない知識がどれか","学習時間の正確な長さ","すべての知識が不要であること","復習が無意味であること"],"answer":"孤立して使えない知識がどれか","explanationKo":"어떤 지식이 고립되어 실제 상황에서 쓰이지 않는지 알 수 있다."},{"prompt":"筆者の考える学び直しとは何か。","options":["知識のつながりを組み替える機会","最初の学習をそのまま繰り返すこと","忘れた事実を隠すこと","新しい内容を避けること"],"answer":"知識のつながりを組み替える機会","explanationKo":"지식의 연결 관계를 재구성하는 기회이다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-12','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0427","prompt":"「領土」の読み方として最も適切なものを選びなさい。","options":["がいりゃく","せつりつ","りょうど","しゅほう"],"answer":"りょうど","explanationKo":"「領土」는 「りょうど」라고 읽는다. 뜻은 영토이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
