INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-12','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0463","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n強い怒りを感じても、（　）を失わず事実を確認してから行動することが大切だ。","options":["審査","移民","討論","理性"],"answer":"理性","explanationKo":"문맥상 「理性」가 가장 자연스럽다. 이성; 합리적으로 판단하는 능력라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
