INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-12','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0518","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新しい都市開発の（　）には、住宅だけでなく教育施設や公園も含まれている。","options":["構想","措置","進化","経過"],"answer":"構想","explanationKo":"문맥상 「構想」가 가장 자연스럽다. 구상; 큰 틀의 계획라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-12','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0529","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n技術の進歩が速いため、（　）が社会の変化に追いついていないという指摘がある。","options":["決意","抑制","楽観","立法"],"answer":"立法","explanationKo":"문맥상 「立法」가 가장 자연스럽다. 입법; 법률 제정라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-12','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0543","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n自分の案だけにこだわらず、（　）的なデータをもとに判断する必要がある。","options":["証言","掲載","客観","定義"],"answer":"客観","explanationKo":"문맥상 「客観」가 가장 자연스럽다. 객관; 객관적인 관점라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
