INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-12','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0661","prompt":"「物事の成り行きを明るく、うまくいくものとして考えること。」という意味に最も近い語を選びなさい。","options":["楽観","移民","構想","停滞"],"answer":"楽観","explanationKo":"「楽観」의 핵심 의미는 낙관; 긍정적으로 전망함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-12','grammar',1,'〜べからず','{"pattern":"〜べからず","meaningKo":"〜해서는 안 된다","explanation":"〜べからず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"初心忘るべからずという言葉を胸に、基本を繰り返し確認した。","ko":"문맥에서 〜해서는 안 된다의 의미로 쓰였다."},{"ja":"関係者以外、ここに立ち入るべからず。","ko":"이 문장도 〜해서는 안 된다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-12','grammar',2,'〜までもない','{"pattern":"〜までもない","meaningKo":"〜할 필요도 없다","explanation":"〜までもない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"結果は言うまでもなく、取り組む過程にも大きな価値がある。","ko":"문맥에서 〜할 필요도 없다의 의미로 쓰였다."},{"ja":"簡単な計算なので、電卓を使うまでもない。","ko":"이 문장도 〜할 필요도 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-12','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n初心忘る（　）という言葉を胸に、基本を繰り返し確認した。","options":["〜とあれば","〜べからず","〜をものともせず","〜そばから"],"answer":"〜べからず","explanationKo":"문맥상 〜해서는 안 된다를 나타내는 「〜べからず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-12','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n結果は言う（　）、取り組む過程にも大きな価値がある。","options":["〜までもない","〜あっての","〜たところで","〜といえども"],"answer":"〜までもない","explanationKo":"문맥상 〜할 필요도 없다를 나타내는 「〜までもない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-12','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n語彙力（　）、文章全体の論理を追う力が求められる。","options":["〜いかんでは","〜だに","〜なくして","〜もさることながら"],"answer":"〜もさることながら","explanationKo":"문맥상 〜도 물론이지만를 나타내는 「〜もさることながら」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-12','reading',1,'選択肢を減らす理由','{"passage":"選択肢が多いことは自由の象徴とされるが、常に満足を高めるとは限らない。比較する項目が増えるほど決定に時間がかかり、選ばなかった案への未練も残りやすい。だからといって、他者が一方的に選択肢を減らせば自由を奪うことになる。必要なのは、本人が目的に照らして比較基準を決め、その基準に合わない案を自ら除くことである。選択肢を減らすとは可能性を捨てることではなく、限られた注意を大切な比較に集中させることだ。","questions":[{"prompt":"選択肢が多すぎる場合の問題は何か。","options":["決定が遅れ未練も残りやすい","自由が必ず失われる","比較項目が減る","目的が自動的に明確になる"],"answer":"決定が遅れ未練も残りやすい","explanationKo":"결정이 늦어지고 선택하지 않은 안에 미련이 남기 쉽다."},{"prompt":"筆者が適切だと考える減らし方はどれか。","options":["本人が目的と基準に沿って除く","他者が一方的に一つだけ残す","比較せず偶然に任せる","すべての案を同時に選ぶ"],"answer":"本人が目的と基準に沿って除く","explanationKo":"본인이 목적과 기준에 따라 선택지를 줄여야 한다."},{"prompt":"選択肢を減らすことの意味は何か。","options":["注意を重要な比較に集中させること","可能性をすべて捨てること","自由を放棄すること","比較基準をなくすこと"],"answer":"注意を重要な比較に集中させること","explanationKo":"한정된 주의를 중요한 비교에 집중하는 것이다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-13','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0737","prompt":"「論議」の読み方として最も適切なものを選びなさい。","options":["しょうげん","けいさい","てんかん","ろんぎ"],"answer":"ろんぎ","explanationKo":"「論議」는 「ろんぎ」라고 읽는다. 뜻은 논의; 논쟁이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
