INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-13','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0988","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n判断を下す前に、客観的な（　）が十分にあるか確認する必要がある。","options":["特権","証拠","権限","福祉"],"answer":"証拠","explanationKo":"문맥상 「証拠」가 가장 자연스럽다. 증거; 증거물라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
