INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-13','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1027","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n障害の影響範囲を正確に（　）してから復旧作業を始める。","options":["主催","討論","紛失","把握"],"answer":"把握","explanationKo":"문맥상 「把握」가 가장 자연스럽다. 파악; 정확히 이해함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
