INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-13','grammar',1,'〜もさることながら','{"pattern":"〜もさることながら","meaningKo":"〜도 물론이지만","explanation":"〜もさることながら는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"商品の性能もさることながら、購入後の支援体制も重要だ。","ko":"문맥에서 〜도 물론이지만의 의미로 쓰였다."},{"ja":"語彙力もさることながら、文章全体の論理を追う力が求められる。","ko":"이 문장도 〜도 물론이지만의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-13','grammar',2,'〜を皮切りに','{"pattern":"〜を皮切りに","meaningKo":"〜을 시작으로","explanation":"〜を皮切りに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"東京公演を皮切りに、全国十都市を巡るツアーが始まる。","ko":"문맥에서 〜을 시작으로의 의미로 쓰였다."},{"ja":"今回の共同研究を皮切りに、両大学は交流を拡大する方針だ。","ko":"이 문장도 〜을 시작으로의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
