INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-13','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n東京公演（　）、全国十都市を巡るツアーが始まる。","options":["〜いかんにかかわらず","〜たりとも","〜ならでは","〜を皮切りに"],"answer":"〜を皮切りに","explanationKo":"문맥상 〜을 시작으로를 나타내는 「〜を皮切りに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-13','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼の置かれた状況を知り、同情（　）。","options":["〜であれ","〜に即して","〜を禁じ得ない","〜ずにはおかない"],"answer":"〜を禁じ得ない","explanationKo":"문맥상 〜을 금할 수 없다를 나타내는 「〜を禁じ得ない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-13','reading',1,'維持される仕組み','{"passage":"新しい制度を始めるとき、人は導入時の効果に注目しやすい。しかし制度は、始める人と維持する人が同じとは限らない。複雑な手順や例外処理を善意だけで支える設計は、担当者が替わると機能しなくなる。維持できる仕組みにするには、通常時の便利さだけでなく、忙しい時でも守れる手順か、誤りを早く発見できるか、役割を引き継げるかを確認する必要がある。持続性は導入後に考える条件ではなく、設計段階の性能なのである。","questions":[{"prompt":"善意だけに依存する設計の問題は何か。","options":["担当者が替わると機能しない可能性がある","導入時の効果が必ず高くなる","手順が自動的に簡単になる","例外処理が不要になる"],"answer":"担当者が替わると機能しない可能性がある","explanationKo":"담당자가 바뀌면 제도가 작동하지 않을 수 있다."},{"prompt":"維持可能性を判断する観点として本文にあるものはどれか。","options":["忙しい時にも守れる手順か","導入した人の人気","制度名の分かりやすさ","開始日の天候"],"answer":"忙しい時にも守れる手順か","explanationKo":"바쁜 상황에서도 지킬 수 있는 절차인지 확인해야 한다."},{"prompt":"筆者は持続性をどのように捉えているか。","options":["設計段階で考えるべき性能","導入後だけの問題","担当者個人の善意","通常時には不要な条件"],"answer":"設計段階で考えるべき性能","explanationKo":"지속성은 설계 단계에서 고려해야 할 성능이다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
