INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-14','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1526","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）の男が店に押し入り、警察が行方を追っている。","options":["権限","福祉","覆面","滞納"],"answer":"覆面","explanationKo":"문맥상 「覆面」가 가장 자연스럽다. 복면; 신원을 숨김라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-14','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1551","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n連休中の問い合わせ増加に備え、サポート（　）を強化した。","options":["言論","態勢","一連","情勢"],"answer":"態勢","explanationKo":"문맥상 「態勢」가 가장 자연스럽다. 태세; 준비 체제라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
