INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-14','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1620","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n山間部では（　）と高齢化が同時に進んでいる。","options":["対処","武装","推測","過疎"],"answer":"過疎","explanationKo":"문맥상 「過疎」가 가장 자연스럽다. 과소화; 인구 과소라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
