INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-14','grammar',1,'〜を禁じ得ない','{"pattern":"〜を禁じ得ない","meaningKo":"〜을 금할 수 없다","explanation":"〜を禁じ得ない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"繰り返される不正の報道に、強い憤りを禁じ得ない。","ko":"문맥에서 〜을 금할 수 없다의 의미로 쓰였다."},{"ja":"彼の置かれた状況を知り、同情を禁じ得なかった。","ko":"이 문장도 〜을 금할 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-14','grammar',2,'〜をものともせず','{"pattern":"〜をものともせず","meaningKo":"〜을 아랑곳하지 않고","explanation":"〜をものともせず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"選手たちは激しい雨をものともせず、最後まで走り続けた。","ko":"문맥에서 〜을 아랑곳하지 않고의 의미로 쓰였다."},{"ja":"彼女は周囲の反対をものともせず、新しい事業に挑戦した。","ko":"이 문장도 〜을 아랑곳하지 않고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-14','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n繰り返される不正の報道に、強い憤り（　）。","options":["〜ずにはおかない","〜であれ","〜に即して","〜を禁じ得ない"],"answer":"〜を禁じ得ない","explanationKo":"문맥상 〜을 금할 수 없다를 나타내는 「〜を禁じ得ない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-14','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n選手たちは激しい雨（　）、最後まで走り続けた。","options":["〜てからというもの","〜にたえる","〜をものともせず","〜ずにはすまない"],"answer":"〜をものともせず","explanationKo":"문맥상 〜을 아랑곳하지 않고를 나타내는 「〜をものともせず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-14','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n顧客（　）商売だという基本を忘れてはならない。","options":["〜に足る","〜あっての","〜そばから","〜てやまない"],"answer":"〜あっての","explanationKo":"문맥상 〜이 있어야 비로소를 나타내는 「〜あっての」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-14','reading',1,'観察するという行為','{"passage":"観察は対象をありのまま見る行為だと思われるが、実際には何を見るかを選んだ時点で解釈が始まっている。同じ教室を見ても、教師は理解度に、建築家は光や動線に注目するだろう。だから観察が主観的で無意味なのではない。自分がどの観点を選び、何を見落とし得るかを明らかにすれば、異なる観察を比較できる。客観性とは観点を持たないことではなく、観点の限界を他者が検討できる形で示すことなのである。","questions":[{"prompt":"筆者によれば、解釈はいつ始まるか。","options":["何を見るかを選んだ時点","観察結果を書いた後","他者と比較した後","対象から離れた時点"],"answer":"何を見るかを選んだ時点","explanationKo":"무엇을 볼지 선택한 순간부터 해석이 시작된다."},{"prompt":"異なる観察を比較するために必要なことは何か。","options":["選んだ観点と見落とす可能性を示すこと","すべて同じ対象を見ること","専門知識を使わないこと","観察者の名前を隠すこと"],"answer":"選んだ観点と見落とす可能性を示すこと","explanationKo":"선택한 관점과 놓칠 가능성을 밝혀야 한다."},{"prompt":"本文でいう客観性とは何か。","options":["観点の限界を検討可能にすること","一切の観点を持たないこと","一人の判断だけを信じること","解釈を完全に禁止すること"],"answer":"観点の限界を検討可能にすること","explanationKo":"관점의 한계를 다른 사람이 검토할 수 있게 제시하는 것이다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
